/* account-sync.js */
(() => {
  if (window.__OC_ACCOUNT_SYNC_READY__) return;

  const PRIMARY_NAME_KEY = 'op-ed-primary-account-name';
  const EVENT_NAME_KEY = 'my-display-name';
  const MAIN_ACCESS_KEY = 'op-ed-access-level';
  const EVENT_ACCESS_KEY = 'event-access-level';
  const PROFILE_CACHE_KEY = 'op-ed-auth-profile-v1';
  const ACCOUNT_MODAL_SELECTOR = '#oc-auth-modal,#oc-register-modal,#oc-name-modal';

  let authBound = false;
  let initialReady = false;
  let personalUid = '';
  let userIntentUntil = 0;
  const startupGuardUntil = Date.now() + 15000;
  let resolveAccountReady;

  window.__OC_ACCOUNT_RESTORE_DONE__ = false;
  window.OC_ACCOUNT_READY = new Promise(resolve => { resolveAccountReady = resolve; });

  function clean(value) {
    return String(value || '').trim();
  }

  function mirrorName(name) {
    const value = clean(name);
    if (!value) return;
    if (localStorage.getItem(PRIMARY_NAME_KEY) !== value) localStorage.setItem(PRIMARY_NAME_KEY, value);
    if (localStorage.getItem(EVENT_NAME_KEY) !== value) localStorage.setItem(EVENT_NAME_KEY, value);
  }

  function cachedProfileName(uid) {
    for (const storage of [sessionStorage, localStorage]) {
      try {
        const cached = JSON.parse(storage.getItem(PROFILE_CACHE_KEY) || 'null');
        if (cached?.uid !== uid || !cached.profile) continue;
        return clean(cached.profile.nickname || cached.profile.nicknameKey || cached.profile.id);
      } catch (_) {}
    }
    return '';
  }

  async function accessForUser(user) {
    try {
      const module = await import('./firebase-config.js');
      const admins = new Set((module.adminUids || []).map(String));
      return admins.has(String(user?.uid || '')) ? 'admin' : 'user';
    } catch (error) {
      console.warn('Could not verify admin role during account restore', error);
      return 'user';
    }
  }

  function finishInitial(authenticated) {
    const detail = { authenticated: Boolean(authenticated), uid: personalUid };
    if (!initialReady) {
      initialReady = true;
      window.__OC_ACCOUNT_RESTORE_DONE__ = true;
      resolveAccountReady?.(detail);
    }
    window.dispatchEvent(new CustomEvent('oped-account-restored', { detail }));
  }

  function hasRecentUserIntent() {
    return Date.now() <= userIntentUntil;
  }

  function markUserIntent() {
    userIntentUntil = Date.now() + 6000;
  }

  function hideUnexpectedAccountModals() {
    if (!personalUid || Date.now() > startupGuardUntil || hasRecentUserIntent()) return;
    document.querySelectorAll(ACCOUNT_MODAL_SELECTOR).forEach(modal => {
      if (!modal.classList.contains('hidden')) modal.classList.add('hidden');
    });
  }

  function suppressRestoreStatus() {
    if (!personalUid || Date.now() > startupGuardUntil || hasRecentUserIntent()) return;
    const status = document.querySelector('#oc-status');
    if (status && /^Вход выполнен:/i.test(clean(status.textContent))) status.textContent = '';
  }

  function bindStartupGuards() {
    document.addEventListener('pointerdown', event => {
      if (event.target?.closest?.('#oc-access-badge,#oc-auth-register-open,#oc-auth-save,#oc-modal-name-save,#oc-register-save')) markUserIntent();
    }, true);
    document.addEventListener('keydown', event => {
      if (event.key === 'Enter' && event.target?.closest?.('#oc-auth-modal,#oc-register-modal,#oc-name-modal')) markUserIntent();
    }, true);

    document.querySelectorAll(ACCOUNT_MODAL_SELECTOR).forEach(modal => {
      new MutationObserver(hideUnexpectedAccountModals).observe(modal, { attributes: true, attributeFilter: ['class'] });
    });

    const status = document.querySelector('#oc-status');
    if (status) new MutationObserver(suppressRestoreStatus).observe(status, { childList: true, characterData: true, subtree: true });
  }

  async function applyUser(user) {
    if (!user || user.isAnonymous) {
      personalUid = '';
      sessionStorage.removeItem(MAIN_ACCESS_KEY);
      if (localStorage.getItem(EVENT_ACCESS_KEY) !== 'guest') localStorage.removeItem(EVENT_ACCESS_KEY);
      finishInitial(false);
      return;
    }

    personalUid = clean(user.uid);
    const level = await accessForUser(user);
    const name = clean(user.displayName) || cachedProfileName(personalUid)
      || clean(localStorage.getItem(PRIMARY_NAME_KEY)) || clean(localStorage.getItem(EVENT_NAME_KEY));

    mirrorName(name);
    sessionStorage.setItem(MAIN_ACCESS_KEY, level);
    if (localStorage.getItem(EVENT_ACCESS_KEY) !== 'guest') localStorage.setItem(EVENT_ACCESS_KEY, level);
    finishInitial(true);

    hideUnexpectedAccountModals();
    suppressRestoreStatus();
    [0, 150, 500, 1200, 3000].forEach(delay => window.setTimeout(() => {
      hideUnexpectedAccountModals();
      suppressRestoreStatus();
    }, delay));
  }

  async function bindAuth(attempt = 0) {
    if (authBound) return;
    try {
      const [{ getApp, getApps }, { getAuth, onAuthStateChanged }] = await Promise.all([
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-auth.js')
      ]);
      if (!getApps().length) {
        if (attempt < 50) window.setTimeout(() => bindAuth(attempt + 1), 100);
        else finishInitial(false);
        return;
      }

      const auth = getAuth(getApp());
      if (typeof auth.authStateReady === 'function') await auth.authStateReady();
      authBound = true;
      await applyUser(auth.currentUser);
      onAuthStateChanged(auth, user => { void applyUser(user); });
    } catch (error) {
      authBound = false;
      console.warn('Account sync skipped', error);
      if (attempt < 10) window.setTimeout(() => bindAuth(attempt + 1), 250);
      else finishInitial(false);
    }
  }

  function init() {
    bindStartupGuards();
    void bindAuth();
  }

  window.addEventListener('storage', event => {
    if ((event.key === PRIMARY_NAME_KEY || event.key === EVENT_NAME_KEY) && personalUid) mirrorName(event.newValue);
  });
  window.addEventListener('oped-db-ready', () => void bindAuth());

  window.__OC_ACCOUNT_SYNC_READY__ = true;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();

/* manual-top-existing-migration.js */
(() => {
  if (window.__OC_MANUAL_TOP_EXISTING_MIGRATION_READY__) return;
  window.__OC_MANUAL_TOP_EXISTING_MIGRATION_READY__ = true;

  const clean = value => String(value ?? '').trim();
  const uniqueIds = values => [...new Set((Array.isArray(values) ? values : []).map(String).filter(Boolean))].slice(0, 100);
  let running = false;
  let completedFor = '';

  function normalize(value) {
    try {
      return window.OPED_DB?.normalizeNickname?.(value)
        || clean(value).toLocaleLowerCase('ru').replace(/[^a-zа-яё0-9_-]+/gi, '_').slice(0, 60);
    } catch (_) {
      return clean(value).toLocaleLowerCase('ru').replace(/[^a-zа-яё0-9_-]+/gi, '_').slice(0, 60);
    }
  }

  function ownUser() {
    return clean(
      document.querySelector('#oc-myname')?.value
      || localStorage.getItem('op-ed-primary-account-name')
      || localStorage.getItem('my-display-name')
    );
  }

  function topFrom(row) {
    if (!row || typeof row !== 'object') return { OP: [], ED: [] };
    return {
      OP: uniqueIds(row.OP || row.manualOP || row.op || []),
      ED: uniqueIds(row.ED || row.manualED || row.ed || [])
    };
  }

  function hasTop(top) {
    return Boolean(top && (top.OP?.length || top.ED?.length));
  }

  function legacyLocalTop(user, key) {
    try {
      const raw = JSON.parse(localStorage.getItem('manual-ranks') || '{}');
      const candidates = [raw?.[user], raw?.[key]];
      for (const row of candidates) {
        const top = topFrom(row);
        if (hasTop(top)) return top;
      }
    } catch (error) {
      console.warn('Could not read legacy local manual top', error);
    }
    return null;
  }

  function visibleManualTop(user, key) {
    const viewed = clean(document.querySelector('#oc-profile-user')?.value || user);
    if (!viewed || normalize(viewed) !== key) return null;

    const manualMode = document.querySelector('#oc-topmode-manual');
    const scoreMode = document.querySelector('#oc-topmode-score');
    if (scoreMode?.classList.contains('active')) return null;
    if (manualMode && !manualMode.classList.contains('active')) return null;

    const collect = selector => {
      const container = document.querySelector(selector);
      if (!container) return [];
      const result = [];
      const seen = new Set();
      container.querySelectorAll(':scope > .oc-profile-item').forEach(card => {
        const id = clean(
          card.dataset.explicitTopId
          || card.querySelector('[data-action="set-rank"][data-id]')?.dataset.id
          || card.querySelector('[data-action="open-card"][data-id]')?.dataset.id
          || card.querySelector('[data-id]')?.dataset.id
        );
        if (!id || seen.has(id) || result.length >= 100) return;
        seen.add(id);
        result.push(id);
      });
      return result;
    };

    const top = { OP: collect('#oc-profile-op'), ED: collect('#oc-profile-ed') };
    return hasTop(top) ? top : null;
  }

  async function waitForDb() {
    if (window.OPED_DB?.saveManualRanks) return window.OPED_DB;
    await Promise.race([
      new Promise(resolve => window.addEventListener('oped-db-ready', resolve, { once: true })),
      new Promise(resolve => setTimeout(resolve, 8000))
    ]);
    return window.OPED_DB?.saveManualRanks ? window.OPED_DB : null;
  }

  async function firebaseTools() {
    const [{ getApp, getApps }, firestore] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js')
    ]);
    for (let attempt = 0; attempt < 120 && !getApps().length; attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    if (!getApps().length) throw new Error('Firebase ещё не готов.');
    return { db: firestore.getFirestore(getApp()), ...firestore };
  }

  async function migrateExistingTop() {
    if (running) return;
    const user = ownUser();
    const key = normalize(user);
    if (!user || !key || completedFor === key) return;

    running = true;
    try {
      const dbApi = await waitForDb();
      if (!dbApi) return;

      const tools = await firebaseTools();
      const manualRef = tools.doc(tools.db, 'manualRanks', key);
      const manualSnap = await tools.getDoc(manualRef);
      const currentTop = manualSnap.exists() ? topFrom(manualSnap.data() || {}) : { OP: [], ED: [] };

      // A non-empty current manualRanks document is authoritative.
      if (hasTop(currentTop)) {
        completedFor = key;
        return;
      }

      // If current storage is empty, recover any real top that still exists in an
      // older mirror, local storage or the already-rendered manual profile view.
      let existingTop = null;
      const profileSnap = await tools.getDoc(tools.doc(tools.db, 'userProfiles', key));
      if (profileSnap.exists()) {
        const profileTop = topFrom(profileSnap.data() || {});
        if (hasTop(profileTop)) existingTop = profileTop;
      }

      if (!existingTop) existingTop = legacyLocalTop(user, key);
      if (!existingTop) existingTop = visibleManualTop(user, key);

      // Do not mark the user as completed yet. The profile/top package may still
      // be rendering; later timers and the observer will retry and can recover it.
      if (!hasTop(existingTop)) return;

      await dbApi.saveManualRanks(user, existingTop);
      completedFor = key;
      try { localStorage.removeItem(`oc-explicit-top-draft-v1:${key}`); } catch (_) {}
      document.dispatchEvent(new CustomEvent('oc:top100-saved', {
        detail: { user, OP: existingTop.OP.slice(), ED: existingTop.ED.slice(), migrated: true }
      }));
      window.OC_TOAST?.show?.('Существующий топ-100 сохранён как актуальный ✓', { type: 'success' });
    } catch (error) {
      console.warn('Existing manual top migration skipped', error);
    } finally {
      running = false;
    }
  }

  function retrySoon() {
    window.setTimeout(migrateExistingTop, 0);
  }

  window.addEventListener('oped-account-restored', retrySoon);
  window.addEventListener('oped-db-ready', retrySoon);
  window.addEventListener('pageshow', () => window.setTimeout(migrateExistingTop, 50));
  document.querySelector('#oc-profile-user')?.addEventListener('change', retrySoon);

  const profile = document.querySelector('#oc-profile-panel');
  if (profile) {
    new MutationObserver(() => retrySoon()).observe(profile, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'data-profile-view'] });
  }

  [0, 300, 1000, 2500, 5000, 8000, 12000].forEach(delay => window.setTimeout(migrateExistingTop, delay));
})();

/* site-policy.js */
(() => {
  if (window.__OC_SITE_POLICY_READY__) return;
  window.__OC_SITE_POLICY_READY__ = true;

  const CONTENT_KEY = 'content-filter-mode';
  const MIGRATION_KEY = 'oc-content-default-all-v1';
  let applyContentOnThisLoad = false;

  try {
    if (localStorage.getItem(MIGRATION_KEY) !== '1') {
      localStorage.setItem(CONTENT_KEY, 'all');
      localStorage.setItem(MIGRATION_KEY, '1');
      applyContentOnThisLoad = true;
    }
  } catch (_) {}

  function removeLegacyProfileManager() {
    document.querySelectorAll('.oc-user-manager').forEach(panel => panel.remove());
  }

  function restoreProfileControls() {
    const selector = document.querySelector('#oc-profile-panel .oc-profile-select-wrap');
    const deleteButton = document.querySelector('#oc-profile-delete-btn');
    if (selector) {
      selector.hidden = false;
      selector.removeAttribute('aria-hidden');
    }
    if (deleteButton) {
      deleteButton.hidden = false;
      deleteButton.removeAttribute('aria-hidden');
    }
  }

  function applyAllContentMode() {
    if (!applyContentOnThisLoad) return;
    const select = document.querySelector('#oc-content-filter-select');
    if (!select) return;
    select.value = 'all';
    select.dispatchEvent(new Event('change', { bubbles: true }));
    applyContentOnThisLoad = false;
  }

  function applyPolicy() {
    removeLegacyProfileManager();
    restoreProfileControls();
    applyAllContentMode();
  }

  new MutationObserver(applyPolicy).observe(document.documentElement, { childList: true, subtree: true });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', applyPolicy, { once: true });
  else applyPolicy();
  [0, 150, 500, 1200].forEach(delay => window.setTimeout(applyPolicy, delay));
})();

/* entity-progress-refresh.js */
(() => {
  const ENTITY_FIELDS = {
    studios: 'studios',
    performers: 'performers',
    directors: 'directors',
    franchises: 'franchises'
  };
  const ENTITY_MIN_TRACKS = 3;

  let openings = [];
  let ratings = [];
  let entityCards = [];
  let lastEntityType = '';
  let refreshTimer = null;
  let identitySignature = '';
  let unsubscribeOpenings = null;
  let unsubscribeRatings = null;
  let unsubscribeEntityCards = null;

  function normalizeValue(value) {
    return String(value || '').trim().toLocaleLowerCase('ru').replace(/\s+/g, ' ');
  }

  function normalizeNickname(value) {
    return String(value || '')
      .trim()
      .toLocaleLowerCase('ru')
      .replace(/[^a-zа-яё0-9_-]+/gi, '_')
      .slice(0, 60);
  }

  function cleanList(value) {
    if (Array.isArray(value)) return value.map(item => String(item || '').trim()).filter(Boolean);
    return String(value || '').split(/[,\n]/).map(item => item.trim()).filter(Boolean);
  }

  function hasNumericValue(value) {
    if (value === null || value === undefined || String(value).trim() === '') return false;
    return Number.isFinite(Number(value));
  }

  function currentIdentity() {
    const name = String(document.querySelector('#oc-myname')?.value || localStorage.getItem('my-display-name') || '').trim();
    const scale = String(document.querySelector('#oc-scale-select')?.value || localStorage.getItem('rating-scale') || 'int');
    return { name, safeName: normalizeNickname(name), personal: scale === 'five', scale };
  }

  function mapHasUserScore(map, safeName) {
    if (!map || typeof map !== 'object' || !safeName) return false;
    return Object.entries(map).some(([nickname, value]) => normalizeNickname(nickname) === safeName && hasNumericValue(value));
  }

  function ratingBelongsToUser(row, safeName) {
    if (!safeName || !row) return false;
    const idNickname = String(row.id || '').split('__')[0];
    return [row.nicknameKey, row.nickname, row.displayName, idNickname]
      .some(value => normalizeNickname(value) === safeName);
  }

  function buildProgressState() {
    const identity = currentIdentity();
    const ratedIds = new Set();
    const index = new Map();

    openings.forEach(opening => {
      const openingId = String(opening?.id || '');
      if (!openingId) return;

      const embeddedScores = identity.personal ? opening.personalScores : opening.scores;
      if (mapHasUserScore(embeddedScores, identity.safeName)) ratedIds.add(openingId);

      Object.entries(ENTITY_FIELDS).forEach(([type, field]) => {
        cleanList(opening[field]).forEach(rawValue => {
          const key = `${type}::${normalizeValue(rawValue)}`;
          if (!index.has(key)) index.set(key, []);
          index.get(key).push(opening);
        });
      });
    });

    ratings.forEach(row => {
      if (!ratingBelongsToUser(row, identity.safeName)) return;
      const value = identity.personal ? row.personalScore : row.score;
      if (!hasNumericValue(value)) return;
      const openingId = String(row.openingId || '').trim();
      if (openingId) ratedIds.add(openingId);
    });

    return { identity, ratedIds, index };
  }

  function activeEntityType() {
    const activeTab = document.querySelector('.oc-tab-btn.active[data-tab^="entity-"]');
    if (activeTab) return String(activeTab.dataset.tab || '').replace(/^entity-/, '');
    if (lastEntityType) return lastEntityType;

    const title = normalizeValue(document.querySelector('#oc-entity-title')?.textContent);
    const matchingCard = entityCards.find(card => normalizeValue(card.value) === title);
    if (matchingCard?.type) return String(matchingCard.type);
    if (title.includes('исполнител')) return 'performers';
    if (title.includes('режисс')) return 'directors';
    if (title.includes('франш')) return 'franchises';
    return 'studios';
  }

  function entityCardInfo(element) {
    const cardId = String(element.getAttribute('data-entity-open') || '');
    const stored = entityCards.find(card => String(card.id || '') === cardId);
    return {
      type: String(stored?.type || activeEntityType()),
      value: String(stored?.value || element.querySelector('h3')?.textContent || '').trim()
    };
  }

  function progressFor(type, value, state) {
    const related = state.index.get(`${type}::${normalizeValue(value)}`) || [];
    const rated = related.reduce((count, opening) => count + (state.ratedIds.has(String(opening.id || '')) ? 1 : 0), 0);
    return {
      related,
      rated,
      complete: related.length >= ENTITY_MIN_TRACKS && rated === related.length
    };
  }

  function updateCard(element, progress) {
    const body = element.querySelector('.oc-entity-card-body');
    if (!body) return;

    const progressText = `${progress.rated} из ${progress.related.length} оценено`;
    const text = body.querySelector(':scope > p');
    if (text && text.textContent !== progressText) text.textContent = progressText;

    const percent = progress.related.length ? Math.round(progress.rated / progress.related.length * 100) : 0;
    const bar = body.querySelector('.oc-entity-progressbar i');
    if (bar && bar.style.width !== `${percent}%`) bar.style.width = `${percent}%`;

    element.classList.toggle('complete', progress.complete);
    element.dataset.rated = String(progress.rated);
    element.dataset.total = String(progress.related.length);
    element.title = progress.complete ? `${progressText}. Альбом полностью закрыт.` : progressText;

    let done = body.querySelector('.oc-entity-done');
    if (progress.complete && !done) {
      done = document.createElement('span');
      done.className = 'oc-entity-done';
      done.textContent = 'Всё просмотрено ✓';
      const deleteButton = body.querySelector('.oc-entity-delete');
      if (deleteButton) body.insertBefore(done, deleteButton);
      else body.append(done);
    } else if (!progress.complete && done) {
      done.remove();
    } else if (done && done.textContent !== 'Всё просмотрено ✓') {
      done.textContent = 'Всё просмотрено ✓';
    }
  }

  function refreshVisibleProgress() {
    const panel = document.querySelector('#oc-entity-panel');
    if (!panel) return;

    const state = buildProgressState();
    panel.querySelectorAll('.oc-entity-card[data-entity-open]').forEach(element => {
      const info = entityCardInfo(element);
      updateCard(element, progressFor(info.type, info.value, state));
    });

    const grid = document.querySelector('#oc-entity-grid');
    if (grid?.classList.contains('hidden')) {
      const title = String(document.querySelector('#oc-entity-title')?.textContent || '').trim();
      const subtitle = document.querySelector('#oc-entity-subtitle');
      if (title && subtitle) {
        const progress = progressFor(activeEntityType(), title, state);
        const text = `${progress.rated} из ${progress.related.length} оценено`;
        if (subtitle.textContent !== text) subtitle.textContent = text;
      }
    }
  }

  function queueProgressRefresh(delay = 40) {
    clearTimeout(refreshTimer);
    refreshTimer = setTimeout(() => {
      refreshTimer = null;
      refreshVisibleProgress();
    }, delay);
  }

  function startWatchers() {
    const db = window.OPED_DB;
    if (!db) return false;

    if (!unsubscribeOpenings && typeof db.watchOpenings === 'function') {
      unsubscribeOpenings = db.watchOpenings(rows => {
        openings = Array.isArray(rows) ? rows : [];
        queueProgressRefresh(70);
      });
    }
    if (!unsubscribeRatings && typeof db.watchRatings === 'function') {
      unsubscribeRatings = db.watchRatings(rows => {
        ratings = Array.isArray(rows) ? rows : [];
        queueProgressRefresh(70);
      });
    }
    if (!unsubscribeEntityCards && typeof db.watchEntityCards === 'function') {
      unsubscribeEntityCards = db.watchEntityCards(rows => {
        entityCards = Array.isArray(rows) ? rows : [];
        queueProgressRefresh(70);
      });
    }

    return Boolean(unsubscribeOpenings && unsubscribeRatings);
  }

  function observeAlbumMarkup() {
    const panel = document.querySelector('#oc-entity-panel');
    if (!panel) return;
    new MutationObserver(records => {
      if (records.some(record => Array.from(record.addedNodes).some(node =>
        node instanceof Element && (node.matches?.('.oc-entity-card') || node.querySelector?.('.oc-entity-card'))
      ))) queueProgressRefresh(0);
    }).observe(panel, { childList: true, subtree: true });
  }

  document.addEventListener('click', event => {
    const launcher = event.target?.closest?.('[data-entity-home]');
    if (launcher) lastEntityType = String(launcher.getAttribute('data-entity-home') || '');

    const album = event.target?.closest?.('.oc-entity-card[data-entity-open]');
    if (album) {
      const cardId = String(album.getAttribute('data-entity-open') || '');
      const stored = entityCards.find(card => String(card.id || '') === cardId);
      if (stored?.type) lastEntityType = String(stored.type);
    }
  }, true);

  document.addEventListener('change', event => {
    if (event.target?.matches?.('#oc-myname, #oc-scale-select')) queueProgressRefresh(0);
  });
  document.addEventListener('input', event => {
    if (event.target?.matches?.('#oc-myname')) queueProgressRefresh(80);
  });
  window.addEventListener('storage', () => queueProgressRefresh(0));

  const identityTimer = setInterval(() => {
    const identity = currentIdentity();
    const next = `${identity.safeName}|${identity.scale}`;
    if (next === identitySignature) return;
    identitySignature = next;
    queueProgressRefresh(0);
  }, 350);

  if (!startWatchers()) {
    window.addEventListener('oped-db-ready', () => {
      startWatchers();
      queueProgressRefresh(100);
    }, { once: true });
    const readyTimer = setInterval(() => {
      if (startWatchers()) clearInterval(readyTimer);
    }, 250);
    setTimeout(() => clearInterval(readyTimer), 15000);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      observeAlbumMarkup();
      queueProgressRefresh(100);
    }, { once: true });
  } else {
    observeAlbumMarkup();
    queueProgressRefresh(100);
  }

  window.addEventListener('beforeunload', () => {
    clearTimeout(refreshTimer);
    clearInterval(identityTimer);
    [unsubscribeOpenings, unsubscribeRatings, unsubscribeEntityCards].forEach(unsubscribe => {
      if (typeof unsubscribe === 'function') unsubscribe();
    });
  }, { once: true });
})();

/* entity-album-editor.js */
(() => {
  if (window.__OC_ENTITY_ALBUM_EDITOR_READY__) return;
  window.__OC_ENTITY_ALBUM_EDITOR_READY__ = true;

  let cards = [];
  let unsubscribe = null;
  let syncTimer = 0;

  const clean = value => String(value || '').trim();
  const isAdmin = () => clean(document.querySelector('#oc-access-badge')?.textContent).toLocaleLowerCase('ru') === 'админ';

  function cardById(id) {
    return cards.find(card => String(card?.id || '') === String(id || '')) || null;
  }

  async function saveBaseCard(card) {
    for (let attempt = 0; attempt < 120 && typeof window.OPED_DB?.saveEntityCard !== 'function'; attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    if (typeof window.OPED_DB?.saveEntityCard !== 'function') throw new Error('Сервис альбомов ещё не готов.');
    return window.OPED_DB.saveEntityCard(card);
  }

  function removeLegacyPositionField() {
    document.querySelector('#oc-entity-image-position')?.closest('.oc-entity-field')?.remove();
  }

  function ensureEditButton(article, card) {
    let button = article.querySelector('.oc-entity-edit');
    if (!isAdmin()) {
      button?.remove();
      return;
    }
    if (!button) {
      button = document.createElement('button');
      button.type = 'button';
      button.className = 'oc-entity-edit';
      button.textContent = '✎';
      button.title = 'Редактировать альбом';
      button.setAttribute('aria-label', 'Редактировать альбом');
      article.append(button);
    }
    button.dataset.entityEdit = String(card.id || '');
  }

  function syncCards() {
    window.clearTimeout(syncTimer);
    removeLegacyPositionField();
    document.querySelectorAll('.oc-entity-card[data-entity-open]').forEach(article => {
      const card = cardById(article.getAttribute('data-entity-open'));
      if (!card) return;
      const image = article.querySelector('.oc-entity-cover img');
      if (image) {
        image.style.removeProperty('object-position');
        delete image.dataset.entityImagePosition;
      }
      ensureEditButton(article, card);
    });
  }

  function queueSync(delay = 0) {
    window.clearTimeout(syncTimer);
    syncTimer = window.setTimeout(syncCards, delay);
  }

  function optionRowsForCard(card) {
    const rows = new Map();
    if (card?.value) rows.set(clean(card.value).toLocaleLowerCase('ru'), clean(card.value));
    document.querySelectorAll('#oc-entity-value option').forEach(option => {
      const value = clean(option.value);
      if (value) rows.set(value.toLocaleLowerCase('ru'), value);
    });
    return [...rows.values()].sort((a, b) => a.localeCompare(b, 'ru'));
  }

  function ensureModal() {
    let modal = document.querySelector('#oc-entity-edit-modal');
    if (modal) return modal;
    modal = document.createElement('div');
    modal.id = 'oc-entity-edit-modal';
    modal.className = 'oc-entity-edit-modal hidden';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    document.body.append(modal);
    return modal;
  }

  function closeModal() {
    const modal = ensureModal();
    modal.classList.add('hidden');
    modal.replaceChildren();
  }

  function escapeHtml(value) {
    const div = document.createElement('div');
    div.textContent = String(value ?? '');
    return div.innerHTML;
  }

  function openModal(card) {
    if (!card || !isAdmin()) return;
    const modal = ensureModal();
    const options = optionRowsForCard(card).map(value => `<option value="${escapeHtml(value)}"${value === clean(card.value) ? ' selected' : ''}>${escapeHtml(value)}</option>`).join('');
    modal.innerHTML = `<div class="oc-entity-edit-dialog" data-entity-edit-id="${escapeHtml(card.id)}">
      <div class="oc-entity-edit-head">
        <div><div class="oc-section-label">редактирование альбома</div><h2>${escapeHtml(card.value)}</h2></div>
        <button type="button" class="oc-entity-edit-close" aria-label="Закрыть">×</button>
      </div>
      <div class="oc-entity-edit-preview-wrap">
        <div class="oc-entity-edit-preview"><img src="${escapeHtml(card.image || '')}" alt="Предпросмотр обложки"></div>
        <div class="oc-entity-edit-preview-note">Так обложка будет выглядеть в квадратной карточке альбома.</div>
      </div>
      <div class="oc-entity-edit-fields">
        <label><span>Объект альбома</span><select data-entity-edit-value>${options}</select></label>
        <label><span>Обложка</span><input data-entity-edit-image type="url" value="${escapeHtml(card.image || '')}" placeholder="https://…/cover.webp"></label>
      </div>
      <div class="oc-entity-edit-actions">
        <button type="button" class="oc-secondary-btn" data-entity-edit-cancel>Отмена</button>
        <button type="button" class="oc-addbtn oc-entity-edit-save" data-entity-edit-save>Сохранить изменения</button>
      </div>
    </div>`;
    modal.classList.remove('hidden');

    const imageInput = modal.querySelector('[data-entity-edit-image]');
    const preview = modal.querySelector('.oc-entity-edit-preview img');
    imageInput?.addEventListener('input', () => {
      if (preview) preview.src = clean(imageInput.value);
    });
  }

  async function saveModal(modal) {
    const dialog = modal.querySelector('[data-entity-edit-id]');
    const id = dialog?.dataset.entityEditId;
    const card = cardById(id);
    if (!card) return;

    const value = clean(modal.querySelector('[data-entity-edit-value]')?.value);
    const image = clean(modal.querySelector('[data-entity-edit-image]')?.value);
    if (!value || !image) {
      window.alert('Укажите объект альбома и ссылку на обложку.');
      return;
    }

    const save = modal.querySelector('[data-entity-edit-save]');
    if (save) {
      save.disabled = true;
      save.textContent = 'Сохраняю…';
    }

    try {
      const newId = await saveBaseCard({ type: card.type, value, image });
      if (String(newId) !== String(id) && typeof window.OPED_DB?.deleteEntityCard === 'function') {
        await window.OPED_DB.deleteEntityCard(id);
      }
      closeModal();
    } catch (error) {
      console.error('Entity album edit failed', error);
      window.alert('Не удалось сохранить изменения альбома.');
      if (save) {
        save.disabled = false;
        save.textContent = 'Сохранить изменения';
      }
    }
  }

  async function subscribeCards() {
    for (let attempt = 0; attempt < 120 && typeof window.OPED_DB?.watchEntityCards !== 'function'; attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    if (typeof window.OPED_DB?.watchEntityCards !== 'function') return;
    unsubscribe = window.OPED_DB.watchEntityCards(rows => {
      cards = Array.isArray(rows) ? rows : [];
      queueSync(0);
    });
  }

  document.addEventListener('click', event => {
    const edit = event.target?.closest?.('[data-entity-edit]');
    if (edit) {
      event.preventDefault();
      event.stopPropagation();
      openModal(cardById(edit.dataset.entityEdit));
      return;
    }

    const modal = event.target?.closest?.('#oc-entity-edit-modal');
    if (!modal) return;
    if (event.target === modal || event.target.closest('.oc-entity-edit-close, [data-entity-edit-cancel]')) {
      closeModal();
      return;
    }
    if (event.target.closest('[data-entity-edit-save]')) void saveModal(modal);
  }, true);

  new MutationObserver(() => queueSync(30)).observe(document.documentElement, { childList: true, subtree: true });
  window.addEventListener('beforeunload', () => { try { unsubscribe?.(); } catch (_) {} }, { once: true });

  removeLegacyPositionField();
  subscribeCards().catch(error => console.warn('Entity album editor failed', error));
  [100, 500, 1200, 2500].forEach(delay => window.setTimeout(() => queueSync(0), delay));
})();

/* entity-real-links.js */
(() => {
	if (window.__OC_ENTITY_REAL_LINKS_READY__) return;
	window.__OC_ENTITY_REAL_LINKS_READY__ = true;

	let syncTimer = 0;
	const clean = value => String(value || '').trim();

	function currentEntityType() {
		const active = document.querySelector('.oc-tab-btn.active[data-tab^="entity-"]');
		if (active?.dataset.tab) return clean(active.dataset.tab).replace(/^entity-/, '');
		const view = new URL(window.location.href).searchParams.get('view') || '';
		return view.startsWith('entity-') ? view.slice('entity-'.length) : '';
	}

	function albumHref(id) {
		const type = currentEntityType();
		if (!type || !id) return '';
		const url = new URL(window.location.href);
		url.search = '';
		url.hash = '';
		url.searchParams.set('view', `entity-${type}`);
		url.searchParams.set('album', String(id));
		return `${url.pathname}${url.search}`;
	}

	function syncBackUrl() {
		const url = new URL(window.location.href);
		const view = clean(url.searchParams.get('view'));
		if (url.searchParams.has('album')) {
			url.searchParams.delete('album');
			url.searchParams.delete('track');
		} else if (view.startsWith('entity-')) {
			url.searchParams.delete('view');
			url.searchParams.delete('album');
			url.searchParams.delete('track');
		}
		window.history.replaceState({}, '', `${url.pathname}${url.search}${url.hash}`);
	}

	function syncLinks() {
		window.clearTimeout(syncTimer);
		document.querySelectorAll('.oc-entity-card[data-entity-open]').forEach(card => {
			const id = clean(card.getAttribute('data-entity-open'));
			if (!id) return;
			let link = card.querySelector(':scope > .oc-entity-card-link');
			if (!link) {
				link = document.createElement('a');
				link.className = 'oc-entity-card-link';
				card.prepend(link);
			}
			link.href = albumHref(id);
			link.dataset.entityAlbumLink = id;
			const title = clean(card.querySelector('.oc-entity-card-body h3')?.textContent);
			link.setAttribute('aria-label', title ? `Открыть альбом «${title}»` : 'Открыть альбом');
			link.title = title ? `Открыть «${title}»` : 'Открыть альбом';
		});
	}

	function queueSync(delay = 0) {
		window.clearTimeout(syncTimer);
		syncTimer = window.setTimeout(syncLinks, delay);
	}

	// Ordinary left click stays inside the SPA. Modified clicks retain native
	// anchor behaviour and must not trigger the old delegated album opener in
	// the current tab.
	document.addEventListener('click', event => {
		if (event.target?.closest?.('#oc-entity-back')) {
			syncBackUrl();
			return;
		}

		const link = event.target?.closest?.('a.oc-entity-card-link[data-entity-album-link]');
		if (!link) return;
		const modified = event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey;
		if (modified) {
			event.stopImmediatePropagation();
			return;
		}
		event.preventDefault();
	}, true);

	new MutationObserver(() => queueSync(20)).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'data-tab'] });
	window.addEventListener('popstate', () => queueSync(0));
	[0, 100, 400, 1000, 2200].forEach(delay => window.setTimeout(syncLinks, delay));
})();

/* top100-rank-readability.js */
(() => {
	if (window.__OC_TOP100_RANK_READABILITY_READY__) return;
	window.__OC_TOP100_RANK_READABILITY_READY__ = true;

	const normalize = value => ({ '①': '1', '②': '2', '③': '3' }[String(value || '').trim()] || String(value || '').trim());
	let timer = 0;

	function syncRanks() {
		window.clearTimeout(timer);
		const selectors = [
			'#oc-profile-panel[data-profile-view="top100"] .oc-profile-rank',
			'#oc-profile-panel[data-profile-view="top100"] .oc-rank-jump-btn',
			'#oc-globaltop-list .oc-profile-rank'
		].join(',');
		document.querySelectorAll(selectors).forEach(rank => {
			const value = normalize(rank.textContent);
			if (value && rank.textContent.trim() !== value) rank.textContent = value;
			if (value) {
				rank.dataset.top100Place = value;
				rank.setAttribute('aria-label', `Место ${value}`);
				if (!rank.title) rank.title = `Место ${value}`;
			}
		});
	}

	function queueSync(delay = 0) {
		window.clearTimeout(timer);
		timer = window.setTimeout(syncRanks, delay);
	}

	new MutationObserver(() => queueSync(25)).observe(document.documentElement, {
		childList: true,
		subtree: true,
		characterData: true,
		attributes: true,
		attributeFilter: ['data-profile-view', 'class']
	});

	document.addEventListener('click', () => queueSync(0), true);
	[0, 100, 400, 1000, 2200].forEach(delay => window.setTimeout(syncRanks, delay));
})();

/* topbar.js */
(() => {
  if (window.__OC_TOPBAR_READY__) return;

  function initTopbar() {
    if (window.__OC_TOPBAR_READY__) return;
    const root = document.querySelector('#opedchart-root');
    const legacyHeader = root?.querySelector('.oc-header');
    const legacyTabs = root?.querySelector('.oc-tabs');
    if (!root || !legacyHeader || !legacyTabs) return;

    const tab = name => legacyTabs.querySelector(`.oc-tab-btn[data-tab="${name}"]`);
    const chartBtn = tab('chart');
    const profileBtn = tab('profile');
    const topBtn = tab('top100');
    const seasonBtn = tab('season');
    const tierBtn = tab('tier');
    const statsBtn = tab('stats');
    const eventsLink = legacyTabs.querySelector('a[href="events.html"]');
    if (!chartBtn || !profileBtn || !seasonBtn || !eventsLink) return;

    const nameInput = document.querySelector('#oc-myname');
    const scaleSelect = document.querySelector('#oc-scale-select');
    const contentSelect = document.querySelector('#oc-content-filter-select');
    const accessBadge = document.querySelector('#oc-access-badge');
    const repairBtn = document.querySelector('#oc-franchise-repair-btn');
    const migrationBtn = document.querySelector('#oc-image-migration-btn');
    const avatarBtn = document.querySelector('#oc-avatar-btn');
    const dailyBtn = document.querySelector('#oc-daily-bell');
    const avatarPicker = document.querySelector('#oc-avatar-picker');
    const mobileMedia = window.matchMedia('(max-width: 900px)');

    const header = document.createElement('header');
    header.className = 'oc-topbar';

    const brand = document.createElement('button');
    brand.type = 'button';
    brand.className = 'oc-topbar-brand';
    brand.textContent = 'АБОБА';
    brand.title = 'Открыть каталог';
    brand.addEventListener('click', () => chartBtn.click());

    const nav = document.createElement('nav');
    nav.className = 'oc-topbar-nav';
    nav.setAttribute('aria-label', 'Основная навигация');

    chartBtn.textContent = 'Каталог';
    profileBtn.textContent = 'Профиль';
    if (tierBtn) tierBtn.textContent = 'Тир-лист';
    seasonBtn.textContent = 'Сезоны';
    eventsLink.textContent = 'Ивенты';
    eventsLink.classList.add('oc-topbar-events');

    nav.append(chartBtn, profileBtn);

    const ratings = document.createElement('details');
    ratings.className = 'oc-topbar-ratings';
    const ratingsSummary = document.createElement('summary');
    ratingsSummary.textContent = 'Рейтинги';
    const ratingsMenu = document.createElement('div');
    ratingsMenu.className = 'oc-topbar-ratings-menu';
    if (topBtn) { topBtn.textContent = 'Общий топ-100'; ratingsMenu.append(topBtn); }
    if (statsBtn) { statsBtn.textContent = 'Средние'; ratingsMenu.append(statsBtn); }
    ratings.append(ratingsSummary, ratingsMenu);
    nav.append(ratings);
    if (tierBtn) nav.append(tierBtn);
    nav.append(seasonBtn, eventsLink);

    const mobileRatingsMenu = document.createElement('div');
    mobileRatingsMenu.className = 'oc-topbar-mobile-ratings-menu';
    mobileRatingsMenu.hidden = true;
    mobileRatingsMenu.setAttribute('role', 'menu');
    mobileRatingsMenu.setAttribute('aria-label', 'Рейтинги');

    function addMobileRatingButton(label, sourceButton) {
      if (!sourceButton) return;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'oc-topbar-mobile-rating-option';
      button.textContent = label;
      button.setAttribute('role', 'menuitem');
      button.addEventListener('click', () => {
        closeMobileRatings();
        sourceButton.click();
      });
      mobileRatingsMenu.append(button);
    }

    addMobileRatingButton('Общий топ-100', topBtn);
    addMobileRatingButton('Средние', statsBtn);
    document.body.append(mobileRatingsMenu);

    const right = document.createElement('div');
    right.className = 'oc-topbar-right';
    if (dailyBtn) right.append(dailyBtn);

    const account = document.createElement('details');
    account.className = 'oc-topbar-account';
    const accountSummary = document.createElement('summary');
    accountSummary.innerHTML = '<span class="oc-topbar-account-avatar">🙂</span><span class="oc-topbar-account-name">Аккаунт</span><span class="oc-topbar-account-chevron">▼</span>';
    const accountMenu = document.createElement('div');
    accountMenu.className = 'oc-topbar-account-menu';

    if (nameInput) {
      const field = document.createElement('label');
      field.className = 'oc-topbar-menu-field';
      field.append('Никнейм');
      const line = document.createElement('div');
      line.className = 'oc-topbar-account-line';
      line.append(nameInput);
      if (accessBadge) line.append(accessBadge);
      field.append(line);
      accountMenu.append(field);
    }

    if (scaleSelect) {
      const field = document.createElement('label');
      field.className = 'oc-topbar-menu-field';
      field.append('Шкала оценки', scaleSelect);
      accountMenu.append(field);
    }

    if (contentSelect) {
      const field = document.createElement('label');
      field.className = 'oc-topbar-menu-field';
      field.append('Контент', contentSelect);
      accountMenu.append(field);
    }

    if (avatarBtn) {
      const avatarRow = document.createElement('div');
      avatarRow.className = 'oc-topbar-avatar-row';
      const label = document.createElement('span');
      label.textContent = 'Аватар';
      avatarRow.append(label, avatarBtn);
      accountMenu.append(avatarRow);
    }
    if (avatarPicker) accountMenu.append(avatarPicker);

    if (repairBtn || migrationBtn) {
      const admin = document.createElement('div');
      admin.className = 'oc-topbar-admin';
      if (repairBtn) admin.append(repairBtn);
      if (migrationBtn) admin.append(migrationBtn);
      accountMenu.append(admin);
    }

    account.append(accountSummary, accountMenu);
    right.append(account);
    header.append(brand, nav, right);
    root.insertBefore(header, legacyHeader);

    legacyHeader.classList.add('oc-topbar-legacy-hidden');
    legacyTabs.classList.add('oc-topbar-legacy-hidden');

    const accountAvatar = accountSummary.querySelector('.oc-topbar-account-avatar');
    const accountName = accountSummary.querySelector('.oc-topbar-account-name');

    function syncAccount() {
      if (accountAvatar && avatarBtn) accountAvatar.textContent = String(avatarBtn.textContent || '🙂').trim() || '🙂';
      if (accountName) {
        const name = String(nameInput?.value || '').trim();
        accountName.textContent = name || 'Аккаунт';
        accountName.title = name || 'Аккаунт';
      }
    }

    function syncRatingsActive() {
      ratings.classList.toggle('active', [topBtn, statsBtn].some(button => button?.classList.contains('active')));
    }

    function positionMobileRatings() {
      if (mobileRatingsMenu.hidden) return;
      const rect = header.getBoundingClientRect();
      mobileRatingsMenu.style.top = `${Math.max(8, Math.round(rect.bottom + 8))}px`;
    }

    function openMobileRatings() {
      ratings.open = false;
      account.open = false;
      mobileRatingsMenu.hidden = false;
      positionMobileRatings();
      ratingsSummary.setAttribute('aria-expanded', 'true');
    }

    function closeMobileRatings() {
      mobileRatingsMenu.hidden = true;
      ratingsSummary.setAttribute('aria-expanded', 'false');
    }

    syncAccount();
    syncRatingsActive();
    ratingsSummary.setAttribute('aria-expanded', 'false');
    nameInput?.addEventListener('input', syncAccount);
    nameInput?.addEventListener('change', syncAccount);
    if (avatarBtn) new MutationObserver(syncAccount).observe(avatarBtn, { childList: true, characterData: true, subtree: true });
    [chartBtn, profileBtn, topBtn, seasonBtn, tierBtn, statsBtn].filter(Boolean).forEach(button => {
      new MutationObserver(syncRatingsActive).observe(button, { attributes: true, attributeFilter: ['class'] });
      button.addEventListener('click', () => {
        ratings.open = false;
        closeMobileRatings();
        account.open = false;
        window.setTimeout(() => { syncAccount(); syncRatingsActive(); }, 0);
      });
    });

    ratingsSummary.addEventListener('click', event => {
      if (!mobileMedia.matches) return;
      event.preventDefault();
      event.stopPropagation();
      if (mobileRatingsMenu.hidden) openMobileRatings();
      else closeMobileRatings();
    });

    account.addEventListener('toggle', () => {
      if (account.open) {
        ratings.open = false;
        closeMobileRatings();
        syncAccount();
      }
    });
    ratings.addEventListener('toggle', () => {
      if (mobileMedia.matches && ratings.open) ratings.open = false;
      if (ratings.open) {
        closeMobileRatings();
        account.open = false;
      }
    });
    document.addEventListener('click', event => {
      if (account.open && !account.contains(event.target)) account.open = false;
      if (ratings.open && !ratings.contains(event.target)) ratings.open = false;
      if (!mobileRatingsMenu.hidden && !mobileRatingsMenu.contains(event.target) && !ratings.contains(event.target)) closeMobileRatings();
    });
    window.addEventListener('resize', () => {
      if (!mobileMedia.matches) closeMobileRatings();
      else positionMobileRatings();
    }, { passive: true });
    window.addEventListener('scroll', positionMobileRatings, { passive: true });

    window.setInterval(syncAccount, 1200);
    window.__OC_TOPBAR_READY__ = true;
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initTopbar, { once: true });
  else initTopbar();
})();

/* profile-tabs.js */
(() => {
  if (window.__OC_PROFILE_TABS_READY__) return;

  const VIEWS = new Set(['overview', 'top100', 'ratings', 'daily', 'events']);
  const STORAGE_KEY = 'oc-profile-subtab';
  let currentView = 'overview';
  let statsEnhanceScheduled = false;

  function panel() {
    return document.querySelector('#oc-profile-panel');
  }

  function setVisible(selector, visible) {
    panel()?.querySelectorAll(selector).forEach(element => {
      element.classList.toggle('oc-profile-section-hidden', !visible);
    });
  }

  function ensureTabs() {
    const root = panel();
    if (!root || root.querySelector('.oc-profile-subtabs')) return;
    const anchor = root.querySelector('.oc-profile-select-wrap');
    if (!anchor) return;

    const tabs = document.createElement('div');
    tabs.className = 'oc-profile-subtabs';
    tabs.setAttribute('role', 'tablist');
    tabs.setAttribute('aria-label', 'Разделы профиля');
    tabs.innerHTML = `
      <button type="button" role="tab" data-profile-view="overview">Обзор</button>
      <button type="button" role="tab" data-profile-view="top100">Мой топ-100</button>
      <button type="button" role="tab" data-profile-view="ratings">Все оценки</button>
      <button type="button" role="tab" data-profile-view="daily">Дейлики</button>
      <button type="button" role="tab" data-profile-view="events">Мои ивенты</button>`;
    anchor.insertAdjacentElement('afterend', tabs);

    tabs.addEventListener('click', event => {
      const button = event.target.closest('[data-profile-view]');
      if (button) setView(button.dataset.profileView, true);
    });

    tabs.addEventListener('keydown', event => {
      if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
      const buttons = [...tabs.querySelectorAll('[data-profile-view]')];
      const activeIndex = buttons.findIndex(button => button.dataset.profileView === currentView);
      if (activeIndex < 0) return;
      event.preventDefault();
      const offset = event.key === 'ArrowRight' ? 1 : -1;
      const next = buttons[(activeIndex + offset + buttons.length) % buttons.length];
      setView(next.dataset.profileView, true);
      next.focus();
    });
  }

  function statLabel(card) {
    return String(card.querySelector('.oc-stat-label')?.textContent || '').trim().toLowerCase();
  }

  function isLeaderStat(card) {
    return /^топ\s*-?\s*\d+/i.test(statLabel(card));
  }

  function statTone(card) {
    const label = statLabel(card);
    if (/(^|[\s·])op($|[\s·])/i.test(label)) return 'op';
    if (/(^|[\s·])ed($|[\s·])/i.test(label)) return 'ed';
    if (label.includes('песня')) return 'song';
    if (label.includes('визуал')) return 'visual';
    return 'neutral';
  }

  function overviewHeading(kind, title, subtitle) {
    const heading = document.createElement('div');
    heading.className = `oc-profile-overview-heading oc-profile-overview-heading-${kind}`;
    const copy = document.createElement('div');
    const kicker = document.createElement('span');
    kicker.textContent = kind === 'summary' ? 'профиль в цифрах' : 'лучшие категории';
    const h3 = document.createElement('h3');
    h3.textContent = title;
    const p = document.createElement('p');
    p.textContent = subtitle;
    copy.append(kicker, h3, p);
    heading.append(copy);
    return heading;
  }

  function enhanceOverviewStats() {
    statsEnhanceScheduled = false;
    const root = panel();
    const stats = root?.querySelector('#oc-profile-stats');
    if (!stats) return;

    const cards = [...stats.children].filter(element => element.classList.contains('oc-stat-card'));
    if (!cards.length) return;

    cards.forEach(card => {
      const leader = isLeaderStat(card);
      card.classList.toggle('oc-profile-metric-card', !leader);
      card.classList.toggle('oc-profile-leader-card', leader);
      card.dataset.profileStatTone = statTone(card);
    });

    const firstMetric = cards.find(card => !isLeaderStat(card));
    const firstLeader = cards.find(isLeaderStat);

    let summary = stats.querySelector('.oc-profile-overview-heading-summary');
    if (!summary) summary = overviewHeading('summary', 'Ключевые показатели', 'Средние оценки и прогресс по каталогу без лишней россыпи карточек.');
    if (firstMetric) stats.insertBefore(summary, firstMetric);

    let leaders = stats.querySelector('.oc-profile-overview-heading-leaders');
    if (firstLeader) {
      if (!leaders) leaders = overviewHeading('leaders', 'Лидеры', 'Студии, исполнители, режиссёры, франшизы и сезоны — крупными, читаемыми блоками.');
      stats.insertBefore(leaders, firstLeader);
    } else if (leaders) {
      leaders.remove();
    }
  }

  function scheduleOverviewStats() {
    if (statsEnhanceScheduled) return;
    statsEnhanceScheduled = true;
    requestAnimationFrame(enhanceOverviewStats);
  }

  function syncManualOwnershipControls() {
    const root = panel();
    if (!root) return;
    const editButton = root.querySelector('#oc-manual-edit-btn');
    const saveButton = root.querySelector('#oc-manual-save-btn');
    if (!editButton && !saveButton) return;

    const ownProfile = Boolean(editButton && !editButton.disabled);
    if (editButton) editButton.style.display = ownProfile ? '' : 'none';
    if (saveButton) saveButton.style.display = ownProfile ? '' : 'none';
  }

  function scheduleManualOwnershipSync() {
    requestAnimationFrame(syncManualOwnershipControls);
  }

  function ensureDailyPlaceholder() {
    const root = panel();
    const daily = root?.querySelector('#oc-daily-panel');
    if (!root || !daily) return null;
    let placeholder = root.querySelector('.oc-profile-daily-placeholder');
    if (!placeholder) {
      placeholder = document.createElement('div');
      placeholder.className = 'oc-profile-daily-placeholder oc-empty';
      placeholder.textContent = 'Настройки ежедневной оценки появятся здесь для выбранного профиля.';
      daily.insertAdjacentElement('afterend', placeholder);
    }
    return placeholder;
  }

  function syncDailyPlaceholder() {
    const root = panel();
    const daily = root?.querySelector('#oc-daily-panel');
    const placeholder = ensureDailyPlaceholder();
    if (!daily || !placeholder) return;
    placeholder.hidden = currentView !== 'daily' || !daily.classList.contains('hidden');
  }

  function setView(view, persist = false) {
    currentView = VIEWS.has(view) ? view : 'overview';
    const root = panel();
    if (!root) return;
    ensureTabs();

    root.dataset.profileView = currentView;
    root.querySelectorAll('.oc-profile-subtabs [data-profile-view]').forEach(button => {
      const active = button.dataset.profileView === currentView;
      button.classList.toggle('active', active);
      button.setAttribute('aria-selected', String(active));
      button.tabIndex = active ? 0 : -1;
    });

    setVisible('#oc-profile-stats', currentView === 'overview');
    setVisible('.oc-topmode-toggle,.oc-topmode-hint,.oc-manual-actions,.oc-profile-columns', currentView === 'top100');
    setVisible('.oc-allratings', currentView === 'ratings');
    setVisible('#oc-daily-panel', currentView === 'daily');
    setVisible('#oc-my-events-panel', currentView === 'events');
    setVisible('.oc-profile-filterbar', currentView === 'top100' || currentView === 'ratings');
    syncDailyPlaceholder();
    scheduleManualOwnershipSync();
    if (currentView === 'overview') scheduleOverviewStats();

    if (persist) {
      try { sessionStorage.setItem(STORAGE_KEY, currentView); } catch (_) {}
    }
  }

  function initProfileTabs() {
    if (window.__OC_PROFILE_TABS_READY__) return;
    const root = panel();
    if (!root) return;

    ensureTabs();
    let saved = 'overview';
    try { saved = sessionStorage.getItem(STORAGE_KEY) || 'overview'; } catch (_) {}
    setView(saved, false);

    const stats = root.querySelector('#oc-profile-stats');
    if (stats) {
      new MutationObserver(scheduleOverviewStats).observe(stats, { childList: true });
      scheduleOverviewStats();
    }

    const editButton = root.querySelector('#oc-manual-edit-btn');
    if (editButton) {
      new MutationObserver(scheduleManualOwnershipSync).observe(editButton, {
        attributes: true,
        attributeFilter: ['disabled']
      });
    }
    root.querySelector('#oc-profile-user')?.addEventListener('change', () => window.setTimeout(syncManualOwnershipControls, 0));
    document.querySelector('#oc-myname')?.addEventListener('change', () => window.setTimeout(syncManualOwnershipControls, 0));
    document.querySelector('#oc-myname')?.addEventListener('input', () => window.setTimeout(syncManualOwnershipControls, 0));
    scheduleManualOwnershipSync();

    const daily = root.querySelector('#oc-daily-panel');
    if (daily) {
      new MutationObserver(() => syncDailyPlaceholder()).observe(daily, {
        attributes: true,
        attributeFilter: ['class'],
        childList: true,
        subtree: true
      });
    }

    document.querySelector('#oc-daily-bell')?.addEventListener('click', () => {
      window.setTimeout(() => {
        if (!root.classList.contains('hidden')) setView('daily', true);
      }, 0);
    });

    window.__OC_PROFILE_TABS_READY__ = true;
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initProfileTabs, { once: true });
  else initProfileTabs();
})();

/* profile-stats-designs.js */
(() => {
  if (window.__OC_PROFILE_STATS_DESIGNS_READY__) return;
  window.__OC_PROFILE_STATS_DESIGNS_READY__ = true;

  let statsObserver = null;
  let observedStats = null;
  let mountQueued = false;

  function statLabel(card) {
    return String(card.querySelector('.oc-stat-label')?.textContent || '').trim().toLowerCase();
  }

  function isLeader(card) {
    return /^топ\s*-?\s*\d+/i.test(statLabel(card));
  }

  function clearTailMeta(card) {
    delete card.dataset.statsTailSize;
    delete card.dataset.statsTailPos;
  }

  function markTail(cards, columns) {
    cards.forEach(clearTailMeta);
    if (!cards.length || cards.length <= columns) return;
    const tailSize = cards.length % columns;
    if (!tailSize) return;
    const start = cards.length - tailSize;
    for (let index = start; index < cards.length; index += 1) {
      cards[index].dataset.statsTailSize = String(tailSize);
      cards[index].dataset.statsTailPos = String(index - start + 1);
    }
  }

  function annotateCards(stats) {
    const allCards = [...stats.querySelectorAll(':scope > .oc-stat-card')];
    allCards.forEach(card => {
      const leader = isLeader(card);
      card.classList.toggle('oc-profile-metric-card', !leader);
      card.classList.toggle('oc-profile-leader-card', leader);
    });

    const metrics = allCards.filter(card => !isLeader(card));
    const leaders = allCards.filter(isLeader);

    metrics.forEach((card, index) => { card.dataset.statsMetricIndex = String(index); });
    leaders.forEach((card, index) => { card.dataset.statsLeaderIndex = String(index); });

    stats.dataset.statsMetricCount = String(metrics.length);
    stats.dataset.statsLeaderCount = String(leaders.length);
    markTail(metrics, 4);
    markTail(leaders, 3);
  }

  function observeStats(stats) {
    if (observedStats === stats) return;
    statsObserver?.disconnect();
    observedStats = stats;
    statsObserver = new MutationObserver(() => queueMount());
    statsObserver.observe(stats, { childList: true });
  }

  function mount() {
    mountQueued = false;
    const stats = document.querySelector('#oc-profile-stats');
    if (!stats) return;

    stats.querySelector(':scope > .oc-stats-design-switch')?.remove();
    stats.dataset.statsDesign = 'showcase';
    annotateCards(stats);
    observeStats(stats);
  }

  function queueMount() {
    if (mountQueued) return;
    mountQueued = true;
    requestAnimationFrame(() => requestAnimationFrame(mount));
  }

  const profile = document.querySelector('#oc-profile-panel');
  if (profile) {
    new MutationObserver(queueMount).observe(profile, {
      attributes: true,
      attributeFilter: ['data-profile-view'],
      childList: true,
      subtree: false
    });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', queueMount, { once: true });
  else queueMount();
})();

/* profile-filters.js */
(() => {
  if (window.__OC_PROFILE_FILTERS_READY__) return;

  function fieldFor(id, root) {
    return root.querySelector(`#${id}`)?.closest('.oc-field') || null;
  }

  function initProfileFilters() {
    if (window.__OC_PROFILE_FILTERS_READY__) return;
    const bar = document.querySelector('#oc-profile-panel .oc-profile-filterbar');
    const grid = bar?.querySelector(':scope > .oc-filtergrid');
    if (!bar || !grid) return;

    const missing = grid.querySelector('#oc-p-missing');
    if (missing) {
      missing.checked = false;
      missing.dispatchEvent(new Event('change', { bubbles: true }));
    }

    const mainIds = ['oc-p-search', 'oc-p-type', 'oc-p-score-cmp', 'oc-p-from-year', 'oc-p-to-year'];
    const advancedIds = ['oc-p-studio', 'oc-p-director', 'oc-p-performer', 'oc-p-franchise'];
    const mainFields = mainIds.map(id => fieldFor(id, grid)).filter((field, index, rows) => field && rows.indexOf(field) === index);
    const advancedFields = advancedIds.map(id => fieldFor(id, grid)).filter(Boolean);
    const reset = grid.querySelector('#oc-p-reset-filters');
    if (!mainFields.length || !advancedFields.length || !reset) return;

    const main = document.createElement('div');
    main.className = 'oc-profile-filter-main';
    mainFields.forEach(field => main.append(field));
    main.append(reset);

    const divider = document.createElement('div');
    divider.className = 'oc-profile-filter-divider';
    divider.innerHTML = '<span>Расширенные фильтры</span>';

    const advanced = document.createElement('div');
    advanced.className = 'oc-profile-filter-advanced';
    advancedFields.forEach(field => advanced.append(field));

    grid.replaceWith(main, divider, advanced);
    bar.classList.add('oc-profile-filterbar-polished');
    window.__OC_PROFILE_FILTERS_READY__ = true;
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initProfileFilters, { once: true });
  else initProfileFilters();
})();

/* active-filter-chips.js */
(() => {
  if (window.__OC_FILTER_CHIPS_READY__) return;

  const SEASONS = { winter: 'Зима', spring: 'Весна', summer: 'Лето', fall: 'Осень' };

  function fire(element, inputToo = false) {
    if (!element) return;
    if (inputToo) element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
  }

  function optionText(select, value) {
    const option = [...(select?.options || [])].find(item => item.value === value);
    return String(option?.textContent || value || '').trim();
  }

  function clearMultiValue(select, value) {
    if (!select) return;
    [...select.options].forEach(option => {
      if (option.value === value) option.selected = false;
    });
    fire(select);
  }

  function chip(label, kind, onClear) {
    return { label, kind, onClear };
  }

  function chipsForScope(scope) {
    const { root, prefix, includeMissing } = scope;
    const rows = [];

    const search = root.querySelector(`#${prefix}-search`);
    const searchValue = String(search?.value || '').trim();
    if (searchValue) rows.push(chip(`Поиск: ${searchValue}`, 'search', () => {
      search.value = '';
      fire(search, true);
    }));

    const type = root.querySelector(`#${prefix}-type`);
    if (type?.value) rows.push(chip(optionText(type, type.value), 'type', () => {
      type.value = '';
      fire(type);
    }));

    const cmp = root.querySelector(`#${prefix}-score-cmp`);
    const score = root.querySelector(`#${prefix}-score-value`);
    const scoreValue = String(score?.value || '').trim();
    if (cmp?.value && scoreValue) rows.push(chip(`Оценка ${cmp.value} ${scoreValue}`, 'score', () => {
      cmp.value = '';
      score.value = '';
      fire(cmp);
      fire(score, true);
    }));

    const fromYear = root.querySelector(`#${prefix}-from-year`);
    const fromSeason = root.querySelector(`#${prefix}-from-season`);
    const toYear = root.querySelector(`#${prefix}-to-year`);
    const toSeason = root.querySelector(`#${prefix}-to-season`);
    if (fromYear?.value || toYear?.value) {
      const from = fromYear?.value ? `${SEASONS[fromSeason?.value] || ''} ${fromYear.value}`.trim() : 'с начала';
      const to = toYear?.value ? `${SEASONS[toSeason?.value] || ''} ${toYear.value}`.trim() : 'до конца';
      rows.push(chip(`Период: ${from} — ${to}`, 'period', () => {
        if (fromYear) { fromYear.value = ''; fire(fromYear); }
        if (toYear) { toYear.value = ''; fire(toYear); }
        if (fromSeason) { fromSeason.value = 'winter'; fire(fromSeason); }
        if (toSeason) { toSeason.value = 'fall'; fire(toSeason); }
      }));
    }

    if (includeMissing) {
      const missing = root.querySelector(`#${prefix}-missing`);
      if (missing?.checked) rows.push(chip('Незаполненные поля', 'missing', () => {
        missing.checked = false;
        fire(missing);
      }));
    }

    [
      ['studio', 'Студия'],
      ['director', 'Режиссёр'],
      ['performer', 'Исполнитель'],
      ['franchise', 'Франшиза']
    ].forEach(([suffix, label]) => {
      const select = root.querySelector(`#${prefix}-${suffix}`);
      if (!select) return;
      [...select.selectedOptions].forEach(option => {
        const value = option.value;
        const shown = String(option.textContent || value).trim();
        if (!value || !shown) return;
        rows.push(chip(`${label}: ${shown}`, suffix, () => clearMultiValue(select, value)));
      });
    });

    return rows;
  }

  function ensureContainer(scope) {
    if (scope.container?.isConnected) return scope.container;
    const existing = scope.root.querySelector(':scope > .oc-filter-chips');
    if (existing) {
      scope.container = existing;
      return existing;
    }
    const container = document.createElement('div');
    container.className = 'oc-filter-chips';
    container.setAttribute('aria-label', 'Активные фильтры');
    const label = scope.root.querySelector(':scope > .oc-section-label');
    if (label) label.insertAdjacentElement('afterend', container);
    else scope.root.prepend(container);
    scope.container = container;
    return container;
  }

  function renderScope(scope) {
    const container = ensureContainer(scope);
    const rows = chipsForScope(scope);
    container.replaceChildren();
    if (!rows.length) return;

    const title = document.createElement('span');
    title.className = 'oc-filter-chips-title';
    title.textContent = 'Активно';
    container.append(title);

    rows.forEach(row => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'oc-filter-chip';
      button.dataset.chipKind = row.kind;
      button.title = `Убрать фильтр «${row.label}»`;

      const label = document.createElement('span');
      label.className = 'oc-filter-chip-label';
      label.textContent = row.label;
      const x = document.createElement('span');
      x.className = 'oc-filter-chip-x';
      x.setAttribute('aria-hidden', 'true');
      x.textContent = '×';
      button.append(label, x);

      button.addEventListener('click', () => {
        row.onClear();
        window.setTimeout(() => renderScope(scope), 0);
      });
      container.append(button);
    });
  }

  function init() {
    if (window.__OC_FILTER_CHIPS_READY__) return;
    const main = document.querySelector('#oc-main-panel > .oc-filterbar');
    const profile = document.querySelector('#oc-profile-panel .oc-profile-filterbar');
    const scopes = [
      main ? { root: main, prefix: 'oc-f', includeMissing: true, container: null } : null,
      profile ? { root: profile, prefix: 'oc-p', includeMissing: false, container: null } : null
    ].filter(Boolean);
    if (!scopes.length) return;

    scopes.forEach(scope => {
      scope.root.addEventListener('input', event => {
        if (event.target.closest('.oc-filter-chip')) return;
        requestAnimationFrame(() => renderScope(scope));
      });
      scope.root.addEventListener('change', event => {
        if (event.target.closest('.oc-filter-chip')) return;
        requestAnimationFrame(() => renderScope(scope));
      });
      scope.root.addEventListener('click', event => {
        if (event.target.closest('.oc-reset-btn')) window.setTimeout(() => renderScope(scope), 20);
      });
    });

    scopes.forEach(renderScope);
    window.__OC_FILTER_CHIPS_READY__ = true;
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();

/* access-role-badge.js */
(() => {
  if (window.__OC_ACCESS_ROLE_BADGE_READY__) return;
  window.__OC_ACCESS_ROLE_BADGE_READY__ = true;

  const badge = document.querySelector('#oc-access-badge');
  if (!badge) return;

  let syncing = false;

  function syncRoleBadge() {
    if (syncing) return;
    syncing = true;
    try {
      const raw = String(badge.textContent || '').trim().toLocaleLowerCase('ru');
      const isAdmin = badge.classList.contains('admin') || raw === 'админ';
      const isUser = !isAdmin && (raw === 'вход' || raw === 'юзер');

      badge.classList.toggle('oc-access-user', isUser);
      badge.classList.toggle('oc-access-guest', !isAdmin && !isUser);

      if (isUser && raw !== 'юзер') badge.textContent = 'юзер';
    } finally {
      syncing = false;
    }
  }

  new MutationObserver(syncRoleBadge).observe(badge, {
    attributes: true,
    attributeFilter: ['class'],
    childList: true,
    characterData: true,
    subtree: true
  });

  window.addEventListener('oped-account-restored', () => window.setTimeout(syncRoleBadge, 0));
  syncRoleBadge();
  [100, 400, 1000].forEach(delay => window.setTimeout(syncRoleBadge, delay));
})();

/* profile-events-ownership.js */
(() => {
  if (window.__OC_PROFILE_EVENTS_OWNERSHIP_READY__) return;
  window.__OC_PROFILE_EVENTS_OWNERSHIP_READY__ = true;

  const clean = value => String(value || '').trim();
  const norm = value => clean(value).toLocaleLowerCase('ru').replace(/ё/g, 'е').replace(/[^a-zа-я0-9_-]+/gi, '_').slice(0, 60);

  function profilePanel() {
    return document.querySelector('#oc-profile-panel');
  }

  function profileSelect() {
    return document.querySelector('#oc-profile-user');
  }

  function eventsTab() {
    return profilePanel()?.querySelector('.oc-profile-subtabs [data-profile-view="events"]');
  }

  function currentAccountName() {
    return clean(
      document.querySelector('#oc-myname')?.value ||
      localStorage.getItem('op-ed-primary-account-name') ||
      localStorage.getItem('my-display-name') || ''
    );
  }

  function selectedProfileName() {
    return clean(profileSelect()?.value);
  }

  function ownProfileSelected() {
    const account = currentAccountName();
    const selected = selectedProfileName();
    return Boolean(account && (!selected || norm(account) === norm(selected)));
  }

  function leaveForeignEventsView() {
    const panel = profilePanel();
    if (!panel || panel.dataset.profileView !== 'events') return;
    panel.querySelector('.oc-profile-subtabs [data-profile-view="overview"]')?.click();
  }

  function syncEventsTabVisibility() {
    const tab = eventsTab();
    if (!tab) return;
    const own = ownProfileSelected();
    tab.hidden = !own;
    tab.style.display = own ? '' : 'none';
    tab.setAttribute('aria-hidden', own ? 'false' : 'true');
    tab.tabIndex = own ? (tab.classList.contains('active') ? 0 : -1) : -1;
    if (!own) leaveForeignEventsView();
  }

  function selectOwnProfile() {
    const select = profileSelect();
    const account = currentAccountName();
    if (!select || !account) return false;
    const option = [...select.options].find(item => norm(item.value || item.textContent) === norm(account));
    if (!option) return false;
    if (select.value !== option.value) {
      select.value = option.value;
      select.dispatchEvent(new Event('change', { bubbles: true }));
    }
    return true;
  }

  function openOwnEvents() {
    const profileButton = document.querySelector('.oc-tab-btn[data-tab="profile"]');
    if (profileButton && !profileButton.classList.contains('active')) profileButton.click();

    const open = () => {
      selectOwnProfile();
      syncEventsTabVisibility();
      const tab = eventsTab();
      if (!tab || tab.hidden) return;
      tab.click();
      tab.focus?.();
    };

    requestAnimationFrame(() => {
      open();
      window.setTimeout(open, 60);
    });
  }

  function eventNoticeActive() {
    const bell = document.querySelector('#oc-daily-bell');
    if (!bell) return false;
    return bell.classList.contains('oc-event-notice') || Number(bell.dataset.eventNoticeCount || 0) > 0;
  }

  function bind() {
    const select = profileSelect();
    select?.addEventListener('change', () => window.setTimeout(syncEventsTabVisibility, 0));
    document.querySelector('#oc-myname')?.addEventListener('input', syncEventsTabVisibility);
    document.querySelector('#oc-myname')?.addEventListener('change', syncEventsTabVisibility);

    document.addEventListener('click', event => {
      const bell = event.target.closest?.('#oc-daily-bell');
      if (!bell || !eventNoticeActive()) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      openOwnEvents();
    }, true);

    const panel = profilePanel();
    if (panel) {
      new MutationObserver(syncEventsTabVisibility).observe(panel, { childList: true, subtree: true });
    }
    if (select) {
      new MutationObserver(syncEventsTabVisibility).observe(select, { childList: true, subtree: true });
    }

    window.addEventListener('oped-account-restored', () => window.setTimeout(syncEventsTabVisibility, 0));
    window.addEventListener('storage', event => {
      if (['op-ed-primary-account-name', 'my-display-name'].includes(event.key)) syncEventsTabVisibility();
    });

    syncEventsTabVisibility();
    [100, 400, 1000, 2500].forEach(delay => window.setTimeout(syncEventsTabVisibility, delay));
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, { once: true });
  else bind();
})();

/* first-user-test-fixes.js */
(() => {
  if (window.__OC_FIRST_USER_TEST_FIXES_READY__) return;
  window.__OC_FIRST_USER_TEST_FIXES_READY__ = true;

  const FIVE_VALUE = 'five';
  const SKLT_KEY = 'sklt';
  let scaleSyncing = false;
  let fiveOptionTemplate = null;

  const clean = value => String(value || '').trim();
  const norm = value => clean(value).toLocaleLowerCase('ru').replace(/ё/g, 'е').replace(/\s+/g, ' ');

  function currentAccountName() {
    return clean(
      document.querySelector('#oc-myname')?.value ||
      localStorage.getItem('op-ed-primary-account-name') ||
      localStorage.getItem('my-display-name') || ''
    );
  }

  function protectOpeningBackdrop() {
    const modal = document.querySelector('#oc-opening-modal');
    if (!modal || modal.dataset.ocIntentionalBackdropBound === '1') return;
    modal.dataset.ocIntentionalBackdropBound = '1';

    let gesture = null;
    modal.addEventListener('pointerdown', event => {
      gesture = {
        pointerId: event.pointerId,
        startedOnBackdrop: event.target === modal,
        startX: event.clientX,
        startY: event.clientY,
        endedOnBackdrop: false,
        moved: false
      };
    }, true);

    modal.addEventListener('pointermove', event => {
      if (!gesture || gesture.pointerId !== event.pointerId) return;
      if (Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) > 7) gesture.moved = true;
    }, true);

    modal.addEventListener('pointerup', event => {
      if (!gesture || gesture.pointerId !== event.pointerId) return;
      gesture.endedOnBackdrop = event.target === modal;
      if (Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) > 7) gesture.moved = true;
    }, true);

    modal.addEventListener('pointercancel', () => { gesture = null; }, true);

    modal.addEventListener('click', event => {
      if (event.target !== modal) return;
      const intentionalBackdropClick = Boolean(
        gesture && gesture.startedOnBackdrop && gesture.endedOnBackdrop && !gesture.moved
      );
      gesture = null;
      if (intentionalBackdropClick) return;
      event.preventDefault();
      event.stopImmediatePropagation();
    }, true);
  }

  function ensureFiveOption(select) {
    if (!fiveOptionTemplate) {
      fiveOptionTemplate = select.querySelector(`option[value="${FIVE_VALUE}"]`)?.cloneNode(true) || null;
    }
    if (select.querySelector(`option[value="${FIVE_VALUE}"]`)) return;
    const option = fiveOptionTemplate || document.createElement('option');
    option.value = FIVE_VALUE;
    option.textContent = option.textContent || 'оценка 1–5';
    select.append(option.cloneNode(true));
  }

  function syncScalePolicy() {
    if (scaleSyncing) return;
    const select = document.querySelector('#oc-scale-select');
    if (!select) return;
    if (!fiveOptionTemplate) fiveOptionTemplate = select.querySelector(`option[value="${FIVE_VALUE}"]`)?.cloneNode(true) || null;

    const allowed = norm(currentAccountName()) === SKLT_KEY;
    const fiveOption = select.querySelector(`option[value="${FIVE_VALUE}"]`);

    scaleSyncing = true;
    try {
      if (allowed) {
        ensureFiveOption(select);
        if (localStorage.getItem('rating-scale') === FIVE_VALUE && select.value !== FIVE_VALUE) {
          select.value = FIVE_VALUE;
          select.dispatchEvent(new Event('change', { bubbles: true }));
        }
      } else {
        const mustReset = select.value === FIVE_VALUE || localStorage.getItem('rating-scale') === FIVE_VALUE;
        if (mustReset) {
          localStorage.setItem('rating-scale', 'int');
          select.value = 'int';
          select.dispatchEvent(new Event('change', { bubbles: true }));
        }
        fiveOption?.remove();
      }
      select.dataset.fivePointOwner = allowed ? 'SKLT' : '';
    } finally {
      scaleSyncing = false;
    }
  }

  function removeLegacyUserManager() {
    document.querySelectorAll('.oc-user-manager').forEach(panel => panel.remove());
  }

  function syncAll() {
    protectOpeningBackdrop();
    syncScalePolicy();
    removeLegacyUserManager();
  }

  const nameInput = document.querySelector('#oc-myname');
  nameInput?.addEventListener('input', syncScalePolicy);
  nameInput?.addEventListener('change', syncScalePolicy);
  const badge = document.querySelector('#oc-access-badge');
  if (badge) new MutationObserver(syncAll).observe(badge, { attributes: true, childList: true, characterData: true, subtree: true });

  document.querySelector('#oc-scale-select')?.addEventListener('change', () => {
    if (norm(currentAccountName()) !== SKLT_KEY && document.querySelector('#oc-scale-select')?.value === FIVE_VALUE) {
      syncScalePolicy();
    }
  }, true);

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', syncAll, { once: true });
  else syncAll();
  [250, 900, 2500, 6000].forEach(delay => window.setTimeout(syncAll, delay));
})();

/* registered-users-only.js */
(() => {
  if (window.__OC_REGISTERED_USERS_ONLY_READY__) return;
  window.__OC_REGISTERED_USERS_ONLY_READY__ = true;

  const PROFILE_LIST_ID = 'oc-profile-user';
  const EVENT_DATALIST_ID = 'ev-known-participants';
  const ADMIN_ORDER = ['пес_кошачий', 'пёс_кошачий', 'toxexex', 'egortos', 'кофа'];
  let knownByKey = new Map();
  let profilesLoaded = false;
  let syncQueued = false;
  let unsubscribe = null;

  const clean = value => String(value || '').trim();
  const normalize = value => clean(value).toLocaleLowerCase('ru').replace(/ё/g, 'е').replace(/[^a-zа-я0-9_-]+/gi, '_').slice(0, 60);

  function profileName(row) {
    return clean(row?.nickname || row?.displayName || row?.name || row?.nicknameKey || row?.id);
  }

  function adminRank(rowOrName) {
    const name = typeof rowOrName === 'string' ? rowOrName : profileName(rowOrName);
    const key = normalize(name);
    const ranks = ['пес_кошачий', 'toxexex', 'egortos', 'кофа'];
    return ranks.indexOf(key);
  }

  function isAdminProfile(rowOrName) {
    return adminRank(rowOrName) >= 0;
  }

  function compareProfiles(a, b) {
    const rankA = adminRank(a);
    const rankB = adminRank(b);
    if (rankA >= 0 || rankB >= 0) {
      if (rankA < 0) return 1;
      if (rankB < 0) return -1;
      return rankA - rankB;
    }
    return profileName(a).localeCompare(profileName(b), 'ru', { sensitivity: 'base' });
  }

  function knownRows(rows) {
    const next = new Map();
    (Array.isArray(rows) ? rows : []).forEach(row => {
      const name = profileName(row);
      const key = normalize(row?.nicknameKey || name || row?.id);
      if (!name || !key) return;
      const existing = next.get(key);
      if (!existing || (!clean(existing.avatar) && clean(row?.avatar))) next.set(key, { ...row, nickname: name, nicknameKey: key });
    });
    return [...next.values()].sort(compareProfiles);
  }

  function setProfiles(rows) {
    const profiles = knownRows(rows);
    knownByKey = new Map(profiles.map(row => [normalize(row.nicknameKey || profileName(row)), row]));
    profilesLoaded = true;
    scheduleSync();
  }

  function currentAccountName() {
    return clean(
      document.querySelector('#oc-myname')?.value ||
      document.querySelector('#ev-myname')?.value ||
      localStorage.getItem('op-ed-primary-account-name') ||
      localStorage.getItem('my-display-name')
    );
  }

  function optionSignature(select) {
    return [...select.options].map(option => `${option.value}\u0000${option.textContent}`).join('\u0001');
  }

  function syncMainProfileSelect() {
    const select = document.getElementById(PROFILE_LIST_ID);
    if (!select || !profilesLoaded || !knownByKey.size) return;

    const profiles = [...knownByKey.values()].sort(compareProfiles);
    const previous = clean(select.value);
    const previousKey = normalize(previous);
    const accountKey = normalize(currentAccountName());
    const selectedRow = knownByKey.get(previousKey) || knownByKey.get(accountKey) || profiles[0];
    const selectedName = profileName(selectedRow);

    const expected = profiles.map(row => {
      const name = profileName(row);
      const avatar = clean(row.avatar) || '🙂';
      const admin = isAdminProfile(row);
      return { value: name, label: `${admin ? '🔧 ' : ''}${avatar} ${name}`, admin };
    });
    const expectedSignature = expected.map(row => `${row.value}\u0000${row.label}`).join('\u0001');
    const selectionChanged = normalize(previous) !== normalize(selectedName);

    if (optionSignature(select) !== expectedSignature) {
      select.replaceChildren(...expected.map(row => {
        const option = document.createElement('option');
        option.value = row.value;
        option.textContent = row.label;
        if (row.admin) option.dataset.admin = '1';
        return option;
      }));
    }
    select.value = selectedName;
    if (selectionChanged) select.dispatchEvent(new Event('change', { bubbles: true }));
  }

  function ensureEventDatalist() {
    if (!profilesLoaded || !knownByKey.size) return null;
    let datalist = document.getElementById(EVENT_DATALIST_ID);
    if (!datalist) {
      datalist = document.createElement('datalist');
      datalist.id = EVENT_DATALIST_ID;
      document.body.append(datalist);
    }
    const profiles = [...knownByKey.values()].sort(compareProfiles);
    const expected = profiles.map(row => ({ name: profileName(row), admin: isAdminProfile(row) }));
    const current = [...datalist.options].map(option => `${option.value}\u0000${option.label || ''}`);
    const signature = expected.map(row => `${row.name}\u0000${row.admin ? '🔧 админ' : ''}`);
    if (current.join('\u0001') !== signature.join('\u0001')) {
      datalist.replaceChildren(...expected.map(row => {
        const option = document.createElement('option');
        option.value = row.name;
        if (row.admin) option.label = '🔧 админ';
        return option;
      }));
    }
    return datalist;
  }

  function syncEventParticipantInputs() {
    ensureEventDatalist();
    document.querySelectorAll('.ev-participant-input').forEach(input => {
      const name = clean(input.value);
      const profile = knownByKey.get(normalize(name));
      if (profile && name !== profileName(profile)) input.value = profileName(profile);
      if (!input.disabled && knownByKey.size) input.setAttribute('list', EVENT_DATALIST_ID);
      input.removeAttribute('data-registered-only');
      if (!input.disabled) input.title = 'Можно выбрать пользователя из списка или ввести гостевой ник вручную';
    });
  }

  function syncAll() {
    syncQueued = false;
    syncMainProfileSelect();
    syncEventParticipantInputs();
  }

  function scheduleSync() {
    if (syncQueued) return;
    syncQueued = true;
    requestAnimationFrame(syncAll);
  }

  async function subscribeProfiles() {
    if (typeof window.OPED_DB?.watchUserProfiles === 'function') {
      unsubscribe = window.OPED_DB.watchUserProfiles(setProfiles);
      return;
    }

    const [{ getApp, getApps }, { getFirestore, collection, onSnapshot }] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js')
    ]);
    for (let attempt = 0; attempt < 120 && !getApps().length; attempt += 1) await new Promise(resolve => setTimeout(resolve, 50));
    if (!getApps().length) return;
    unsubscribe = onSnapshot(collection(getFirestore(getApp()), 'userProfiles'), snapshot => {
      setProfiles(snapshot.docs.map(docSnap => ({ id: docSnap.id, ...docSnap.data() })));
    }, error => console.warn('Known users list load failed', error));
  }

  document.addEventListener('change', event => {
    const input = event.target?.closest?.('.ev-participant-input');
    if (!input || !profilesLoaded) return;
    const profile = knownByKey.get(normalize(input.value));
    if (profile) input.value = profileName(profile);
  }, true);

  new MutationObserver(scheduleSync).observe(document.documentElement, { childList: true, subtree: true });
  window.addEventListener('beforeunload', () => { try { unsubscribe?.(); } catch (_) {} }, { once: true });

  subscribeProfiles().catch(error => console.warn('Known users helper failed', error));
  [100, 500, 1200, 2500].forEach(delay => window.setTimeout(scheduleSync, delay));
})();

/* admin-profile-picker.js */
(() => {
	if (window.__OC_ADMIN_PROFILE_PICKER_READY__) return;
	window.__OC_ADMIN_PROFILE_PICKER_READY__ = true;

	const select = document.getElementById('oc-profile-user');
	if (!select) return;

	const cleanLabel = value => String(value || '').replace(/^🔧\s*/u, '').trim();
	let lastSignature = '';

	const picker = document.createElement('div');
	picker.className = 'oc-profile-picker';

	const toggle = document.createElement('button');
	toggle.type = 'button';
	toggle.className = 'oc-profile-picker-toggle';
	toggle.setAttribute('aria-haspopup', 'listbox');
	toggle.setAttribute('aria-expanded', 'false');

	const menu = document.createElement('div');
	menu.className = 'oc-profile-picker-menu hidden';
	menu.setAttribute('role', 'listbox');

	select.parentNode.insertBefore(picker, select);
	picker.append(select, toggle, menu);
	select.classList.add('oc-profile-user-native');

	function closeMenu() {
		picker.classList.remove('open');
		menu.classList.add('hidden');
		toggle.setAttribute('aria-expanded', 'false');
	}

	function openMenu() {
		picker.classList.add('open');
		menu.classList.remove('hidden');
		toggle.setAttribute('aria-expanded', 'true');
		menu.querySelector('.selected')?.scrollIntoView({ block: 'nearest' });
	}

	function syncSelection() {
		const selected = select.selectedOptions?.[0] || [...select.options].find(option => option.value === select.value) || select.options[0];
		if (!selected) {
			toggle.textContent = 'Выберите профиль';
			toggle.classList.remove('is-admin');
			return;
		}
		toggle.textContent = cleanLabel(selected.textContent);
		toggle.classList.toggle('is-admin', selected.dataset.admin === '1');
		menu.querySelectorAll('.oc-profile-picker-option').forEach(button => {
			button.classList.toggle('selected', button.dataset.value === select.value);
			button.setAttribute('aria-selected', button.dataset.value === select.value ? 'true' : 'false');
		});
	}

	function renderOptions() {
		const rows = [...select.options].map(option => ({
			value: option.value,
			label: cleanLabel(option.textContent),
			admin: option.dataset.admin === '1'
		}));
		const signature = rows.map(row => `${row.value}\u0000${row.label}\u0000${row.admin ? 1 : 0}`).join('\u0001');
		if (signature !== lastSignature) {
			lastSignature = signature;
			menu.replaceChildren(...rows.map(row => {
				const button = document.createElement('button');
				button.type = 'button';
				button.className = `oc-profile-picker-option${row.admin ? ' is-admin' : ''}`;
				button.dataset.value = row.value;
				button.setAttribute('role', 'option');

				const label = document.createElement('span');
				label.className = 'oc-profile-picker-option-label';
				label.textContent = row.label;
				button.append(label);

				if (row.admin) {
					const crown = document.createElement('span');
					crown.className = 'oc-profile-admin-crown';
					crown.textContent = '♛';
					crown.title = 'Администратор';
					crown.setAttribute('aria-label', 'Администратор');
					button.append(crown);
				}
				return button;
			}));
		}
		syncSelection();
	}

	toggle.addEventListener('click', () => {
		if (menu.classList.contains('hidden')) openMenu();
		else closeMenu();
	});

	menu.addEventListener('click', event => {
		const button = event.target.closest('.oc-profile-picker-option');
		if (!button) return;
		if (select.value !== button.dataset.value) {
			select.value = button.dataset.value;
			select.dispatchEvent(new Event('change', { bubbles: true }));
		}
		syncSelection();
		closeMenu();
		toggle.focus();
	});

	select.addEventListener('change', syncSelection);
	document.addEventListener('pointerdown', event => {
		if (!picker.contains(event.target)) closeMenu();
	});
	document.addEventListener('keydown', event => {
		if (event.key === 'Escape' && !menu.classList.contains('hidden')) {
			closeMenu();
			toggle.focus();
		}
	});

	new MutationObserver(renderOptions).observe(select, {
		childList: true,
		subtree: true,
		characterData: true,
		attributes: true,
		attributeFilter: ['data-admin', 'value', 'selected']
	});

	renderOptions();
	[100, 400, 1000, 2500].forEach(delay => window.setTimeout(renderOptions, delay));
})();

/* admin-missing-inline.js */
(() => {
  if (window.__OC_ADMIN_MISSING_INLINE_READY__) return;
  window.__OC_ADMIN_MISSING_INLINE_READY__ = true;

  const ADMIN_CLASS = 'oc-admin-missing-tools';
  const MARKER_SELECTOR = '.oc-missing-link';
  const REQUIRED_EDIT_FIELDS = [
    '.oc-e-title',
    '.oc-e-year',
    '.oc-e-season',
    '.oc-e-studio',
    '.oc-e-director',
    '.oc-e-performer',
    '.oc-e-franchise',
    '.oc-e-image',
    '.oc-e-link'
  ];
  const FORM_HOTKEY_SELECTOR = [
    '#oc-add-type',
    '.oc-e-type',
    '#oc-add-season',
    '.oc-e-season',
    '.oc-addbar input[type="checkbox"]',
    '.oc-editcard input[type="checkbox"]'
  ].join(', ');
  const ENTRY_DATA_KEYS = ['id', 'openingId', 'trackId', 'entryId', 'qualityTrack'];
  let hoveredFormHotkeyControl = null;
  let markerOpenPending = false;

  function isAdminUi() {
    const badge = document.querySelector('#oc-access-badge');
    return Boolean(
      badge &&
      badge.classList.contains('admin') &&
      String(badge.textContent || '').trim().toLocaleLowerCase('ru') === 'админ'
    );
  }

  function syncAdminClass() {
    const admin = isAdminUi();
    document.documentElement.classList.toggle(ADMIN_CLASS, admin);
    if (admin) enhanceMissingMarkers(document);
  }

  function editableControls(scope) {
    if (!scope) return [];
    return [...scope.querySelectorAll(
      'input:not([type="hidden"]):not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled])'
    )].filter(control => {
      if (!(control instanceof HTMLElement)) return false;
      if (control.getAttribute('aria-hidden') === 'true') return false;
      const style = window.getComputedStyle(control);
      return style.display !== 'none' && style.visibility !== 'hidden' && control.getClientRects().length > 0;
    });
  }

  function firstMissingEditField(editor) {
    for (const selector of REQUIRED_EDIT_FIELDS) {
      const control = editor.querySelector(selector);
      if (!control) continue;
      const value = String(control.value || '').trim();
      if (!value) return control;
    }
    return editor.querySelector('input, select, textarea, button');
  }

  function focusInlineEditor(id) {
    const editor = [...document.querySelectorAll('#oc-list-container .oc-editcard')]
      .find(card => String(card.dataset.id || '') === String(id || ''));
    if (!editor) return false;

    editor.classList.add('oc-missing-editor-open');
    editor.scrollIntoView({ behavior: 'smooth', block: 'center' });
    window.setTimeout(() => editor.classList.remove('oc-missing-editor-open'), 1100);

    const control = firstMissingEditField(editor);
    if (!control) return true;
    control.focus({ preventScroll: true });
    if (control instanceof HTMLInputElement && ['text', 'number', 'url', 'search'].includes(control.type)) {
      try { control.select(); } catch (_) {}
    }
    return true;
  }

  function dataValue(element) {
    if (!(element instanceof HTMLElement)) return '';
    for (const key of ENTRY_DATA_KEYS) {
      const value = String(element.dataset?.[key] || '').trim();
      if (value) return value;
    }
    const edit = element.matches?.('[data-action="edit"][data-id]')
      ? element
      : element.querySelector?.('[data-action="edit"][data-id]');
    return String(edit?.dataset?.id || '').trim();
  }

  function markerEntryId(marker) {
    let node = marker;
    while (node && node !== document.documentElement) {
      const value = dataValue(node);
      if (value) return value;
      node = node.parentElement;
    }

    const href = marker.closest('a[href]')?.href || '';
    if (href) {
      try {
        const url = new URL(href, location.href);
        const value = url.searchParams.get('track') || url.searchParams.get('opening') || url.searchParams.get('id');
        if (value) return String(value);
      } catch (_) {}
    }

    const modal = marker.closest('#oc-opening-modal, .oc-opening-modal, .oc-modal');
    if (modal && !modal.classList.contains('hidden')) {
      try {
        const value = new URL(location.href).searchParams.get('track');
        if (value) return String(value);
      } catch (_) {}
    }
    return '';
  }

  function markerEntryTitle(marker) {
    const direct = String(
      marker.dataset?.openingTitle ||
      marker.dataset?.trackTitle ||
      marker.dataset?.title || ''
    ).trim();
    if (direct) return direct;

    const scope = marker.closest(
      '.oc-main-card, .oc-unified-card, .oc-profile-item, .oc-season-card, .oc-modal-card, article, li, tr'
    ) || marker.parentElement;
    const titleElement = scope?.querySelector?.(
      '[data-opening-title], [data-track-title], .oc-card-title, .oc-unified-title, .oc-opening-title, .oc-title-link, h2, h3, h4'
    );
    return String(
      titleElement?.dataset?.openingTitle ||
      titleElement?.dataset?.trackTitle ||
      titleElement?.textContent || ''
    ).replace(/😡/g, '').trim();
  }

  function mainRowById(id) {
    if (!id) return null;
    return [...document.querySelectorAll('#oc-list-container .oc-main-card')]
      .find(row => String(row.dataset.id || '') === String(id));
  }

  function mainRowByTitle(title) {
    const target = String(title || '').trim().toLocaleLowerCase('ru').replace(/ё/g, 'е');
    if (!target) return null;
    return [...document.querySelectorAll('#oc-list-container .oc-main-card')].find(row => {
      const shown = String(row.querySelector('.oc-card-title, .oc-title-link, h2, h3, h4')?.textContent || '')
        .trim().toLocaleLowerCase('ru').replace(/ё/g, 'е');
      return shown === target || shown.includes(target) || target.includes(shown);
    }) || null;
  }

  function openRowEditor(row, id) {
    const editButton = row?.querySelector('[data-action="edit"]');
    if (!(editButton instanceof HTMLElement)) return false;
    const resolvedId = String(id || row.dataset.id || editButton.dataset.id || '').trim();
    editButton.click();
    requestAnimationFrame(() => requestAnimationFrame(() => focusInlineEditor(resolvedId)));
    return true;
  }

  function dispatchFilterChange(control) {
    if (!control) return;
    control.dispatchEvent(new Event('input', { bubbles: true }));
    control.dispatchEvent(new Event('change', { bubbles: true }));
  }

  function prepareMainList(title) {
    document.querySelector('.oc-tab-btn[data-tab="chart"]')?.click();

    const search = document.querySelector('#oc-f-search');
    if (search && title) {
      search.value = title;
      dispatchFilterChange(search);
    }
  }

  function waitForMainRow(id, title, attempts = 24) {
    return new Promise(resolve => {
      const check = left => {
        const row = mainRowById(id) || mainRowByTitle(title);
        if (row || left <= 0) {
          resolve(row || null);
          return;
        }
        window.setTimeout(() => check(left - 1), 45);
      };
      check(attempts);
    });
  }

  async function openInlineEditor(marker) {
    if (!isAdminUi() || markerOpenPending) return;

    const directRow = marker.closest('#oc-list-container .oc-main-card');
    const directId = String(directRow?.dataset.id || '').trim();
    if (directRow && openRowEditor(directRow, directId)) return;

    markerOpenPending = true;
    try {
      const id = markerEntryId(marker);
      const title = markerEntryTitle(marker);

      const localEdit = marker.closest('[data-id], [data-opening-id], [data-track-id], article, li, tr')
        ?.querySelector?.('[data-action="edit"]');
      if (localEdit instanceof HTMLElement) {
        localEdit.click();
        requestAnimationFrame(() => requestAnimationFrame(() => focusInlineEditor(id)));
        return;
      }

      prepareMainList(title);
      let row = await waitForMainRow(id, title, 10);

      if (!row) {
        document.querySelector('#oc-reset-filters')?.click();
        if (title) {
          const search = document.querySelector('#oc-f-search');
          if (search) {
            search.value = title;
            dispatchFilterChange(search);
          }
        }
        row = await waitForMainRow(id, title, 18);
      }

      if (row) openRowEditor(row, id || row.dataset.id);
    } finally {
      markerOpenPending = false;
    }
  }

  function enhanceMarker(marker) {
    if (!(marker instanceof HTMLElement)) return;
    marker.classList.add('oc-missing-edit-trigger');
    marker.setAttribute('role', 'button');
    marker.setAttribute('tabindex', '0');
    marker.setAttribute('aria-label', marker.title
      ? `Редактировать незаполненные поля. ${marker.title}`
      : 'Редактировать незаполненные поля');
  }

  function enhanceMissingMarkers(root) {
    if (!(root instanceof Element || root instanceof Document)) return;
    if (root instanceof Element && root.matches(MARKER_SELECTOR)) enhanceMarker(root);
    root.querySelectorAll?.(MARKER_SELECTOR).forEach(enhanceMarker);
  }

  function dispatchFormControlChange(control) {
    control.dispatchEvent(new Event('input', { bubbles: true }));
    control.dispatchEvent(new Event('change', { bubbles: true }));
  }

  function resolveFormHotkeyControl(event) {
    const focused = event.target instanceof HTMLElement && event.target.matches(FORM_HOTKEY_SELECTOR)
      ? event.target
      : null;
    if (focused) return focused;
    if (hoveredFormHotkeyControl?.isConnected && hoveredFormHotkeyControl.matches(FORM_HOTKEY_SELECTOR)) {
      return hoveredFormHotkeyControl;
    }
    return null;
  }

  function handleFieldChoiceHotkeys(event) {
    if (!isAdminUi() || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const control = resolveFormHotkeyControl(event);
    if (!(control instanceof HTMLElement)) return;
    if (!control.closest('.oc-addbar, .oc-editcard')) return;

    if (control.matches('#oc-add-type, .oc-e-type') && (event.key === '1' || event.key === '2')) {
      event.preventDefault();
      event.stopPropagation();
      control.value = event.key === '1' ? 'OP' : 'ED';
      dispatchFormControlChange(control);
      return;
    }

    if (control.matches('#oc-add-season, .oc-e-season') && ['1', '2', '3', '4'].includes(event.key)) {
      event.preventDefault();
      event.stopPropagation();
      control.value = { '1': 'winter', '2': 'spring', '3': 'summer', '4': 'fall' }[event.key];
      dispatchFormControlChange(control);
      return;
    }

    if (control.matches('input[type="checkbox"]') && event.key === 'Enter') {
      event.preventDefault();
      event.stopPropagation();
      control.checked = !control.checked;
      dispatchFormControlChange(control);
    }
  }

  function handleFormArrowNavigation(event) {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || !isAdminUi()) return;
    if (!(event.target instanceof HTMLElement)) return;

    const scope = event.target.closest('.oc-addbar, .oc-editcard');
    if (!scope) return;

    const controls = editableControls(scope);
    const currentIndex = controls.indexOf(event.target);
    if (currentIndex < 0) return;

    const delta = event.key === 'ArrowRight' ? 1 : -1;
    const next = controls[currentIndex + delta];
    if (!next) return;

    event.preventDefault();
    event.stopPropagation();
    next.focus({ preventScroll: true });
    next.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });

    if (next instanceof HTMLInputElement && ['text', 'number', 'url', 'search'].includes(next.type)) {
      try { next.select(); } catch (_) {}
    }
  }

  const badge = document.querySelector('#oc-access-badge');
  if (badge) {
    new MutationObserver(syncAdminClass).observe(badge, {
      attributes: true,
      attributeFilter: ['class'],
      childList: true,
      characterData: true,
      subtree: true
    });
  }

  const root = document.querySelector('#opedchart-root') || document.documentElement;
  new MutationObserver(records => {
    records.forEach(record => record.addedNodes.forEach(node => {
      if (node instanceof Element) enhanceMissingMarkers(node);
    }));
    syncAdminClass();
  }).observe(root, { childList: true, subtree: true });

  document.addEventListener('click', event => {
    const marker = event.target instanceof Element ? event.target.closest(MARKER_SELECTOR) : null;
    if (!marker || !isAdminUi()) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    void openInlineEditor(marker);
  }, true);

  document.addEventListener('keydown', event => {
    const marker = event.target instanceof Element ? event.target.closest(MARKER_SELECTOR) : null;
    if (marker && isAdminUi() && (event.key === 'Enter' || event.key === ' ')) {
      event.preventDefault();
      event.stopImmediatePropagation();
      void openInlineEditor(marker);
      return;
    }
    handleFieldChoiceHotkeys(event);
    handleFormArrowNavigation(event);
  }, true);

  document.addEventListener('pointerover', event => {
    const control = event.target instanceof Element ? event.target.closest(FORM_HOTKEY_SELECTOR) : null;
    hoveredFormHotkeyControl = control && control.closest('.oc-addbar, .oc-editcard') ? control : null;
  }, true);
  document.addEventListener('pointerout', event => {
    if (!hoveredFormHotkeyControl) return;
    const next = event.relatedTarget instanceof Element ? event.relatedTarget.closest(FORM_HOTKEY_SELECTOR) : null;
    if (next === hoveredFormHotkeyControl) return;
    hoveredFormHotkeyControl = null;
  }, true);

  syncAdminClass();
})();

/* my-events-profile.js */
(() => {
  if (window.__OC_MY_EVENTS_PROFILE_READY__) return;
  window.__OC_MY_EVENTS_PROFILE_READY__ = true;

  const CURRENT_EVENT_YEAR = 2026;
  const SEASONS = ['winter', 'spring', 'summer', 'fall'];
  const SEASON_LABEL = { winter:'Зима', spring:'Весна', summer:'Лето', fall:'Осень' };
  const ASSIGNMENT_SEEN_PREFIX = 'oc-event-assignment-seen-v1:';
  let loadedForUid = '';
  let loading = false;
  let lastData = null;

  const clean = value => String(value || '').trim();
  const norm = value => clean(value).toLowerCase().replace(/[^a-zа-яё0-9_-]+/gi, '_').slice(0,60);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[ch]));

  function root() { return document.querySelector('#oc-profile-panel'); }
  function tab() { return root()?.querySelector('.oc-profile-subtabs [data-profile-view="events"]'); }
  function bell() { return document.querySelector('#oc-daily-bell'); }

  function ensurePanel() {
    const profile = root();
    if (!profile) return null;
    let panel = profile.querySelector('#oc-my-events-panel');
    if (!panel) {
      panel = document.createElement('section');
      panel.id = 'oc-my-events-panel';
      panel.className = 'oc-my-events-panel';
      const anchor = profile.querySelector('#oc-daily-panel') || profile.querySelector('.oc-allratings') || profile.lastElementChild;
      anchor?.insertAdjacentElement('afterend', panel);
    }
    panel.classList.toggle('oc-profile-section-hidden', profile.dataset.profileView !== 'events');
    return panel;
  }

  function seenAssignments(uid) {
    try {
      const raw = JSON.parse(localStorage.getItem(`${ASSIGNMENT_SEEN_PREFIX}${uid}`) || '[]');
      return new Set(Array.isArray(raw) ? raw.map(String) : []);
    } catch (_) { return new Set(); }
  }

  function markSeen(uid, key) {
    const seen = seenAssignments(uid);
    seen.add(String(key));
    try { localStorage.setItem(`${ASSIGNMENT_SEEN_PREFIX}${uid}`, JSON.stringify([...seen])); } catch (_) {}
    updateNoticeBadge(lastData);
  }

  function bindingRows(row) { return Array.isArray(row?.participantBindings) ? row.participantBindings : []; }

  function accessibleSeason(row, nickname, uid) {
    if (!row || row.closed || Number(row.year || CURRENT_EVENT_YEAR) !== CURRENT_EVENT_YEAR) return null;
    const key = norm(nickname);
    const slots = Array.isArray(row.allowedNicknames) ? row.allowedNicknames : [];
    const slotIndex = slots.findIndex(name => norm(name) === key);
    if (slotIndex < 0 || slotIndex >= 15) return null;
    const binding = bindingRows(row).find(item => norm(item?.nicknameKey || item?.nickname) === key);
    if (binding?.authUid && String(binding.authUid) !== String(uid)) return null;
    return { ...row, key:String(row.key || row.id || `${CURRENT_EVENT_YEAR}_${row.season || ''}`), slot:slotIndex+1, selectedOpeningIds:Array.isArray(row.selectedOpeningIds) ? row.selectedOpeningIds.map(String) : [], accountLinked:Boolean(binding?.authUid ? String(binding.authUid) === String(uid) : true) };
  }

  async function firebaseTools() {
    const [{ getApp, getApps }, firestore, authModule] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js'),
      import('https://www.gstatic.com/firebasejs/12.15.0/firebase-auth.js')
    ]);
    for (let attempt=0; attempt<100 && !getApps().length; attempt+=1) await new Promise(resolve => setTimeout(resolve,50));
    if (!getApps().length) throw new Error('Firebase ещё не готов.');
    const app = getApp();
    return { app, auth:authModule.getAuth(app), db:firestore.getFirestore(app), ...firestore };
  }

  async function accountProfile(tools, user) {
    const snapshot = await tools.getDocs(tools.query(tools.collection(tools.db,'userProfiles'), tools.where('authUid','==',String(user.uid)), tools.limit(1)));
    const docSnap = snapshot.docs[0];
    if (!docSnap) return null;
    const row = { id:docSnap.id, ...docSnap.data() };
    const nickname = clean(row.nickname || row.nicknameKey || docSnap.id);
    return nickname ? { ...row, nickname, nicknameKey:norm(row.nicknameKey || nickname) } : null;
  }

  async function loadData(force = false) {
    if (loading) return lastData;
    const tools = await firebaseTools();
    if (typeof tools.auth.authStateReady === 'function') await tools.auth.authStateReady();
    const user = tools.auth.currentUser;
    if (!user || user.isAnonymous) return null;
    if (!force && loadedForUid === user.uid && lastData) return lastData;
    loading = true;
    try {
      const profile = await accountProfile(tools, user);
      if (!profile?.nicknameKey) return null;
      const nickname = profile.nickname;
      const nicknameKey = profile.nicknameKey;
      const seasonPromise = tools.getDocs(tools.collection(tools.db,'eventSeasons'));
      const ratingPromise = tools.getDocs(tools.query(tools.collection(tools.db,'eventRatings'), tools.where('nicknameKey','==',nicknameKey)));
      const reminderPromise = tools.getDocs(tools.query(tools.collection(tools.db,'eventNotifications'), tools.where('recipientUid','==',String(user.uid)))).catch(error => {
        console.warn('My Events reminders load skipped', error);
        return null;
      });
      const [seasonSnapshot, ratingSnapshot, reminderSnapshot] = await Promise.all([seasonPromise, ratingPromise, reminderPromise]);
      const seasons = seasonSnapshot.docs.map(docSnap => accessibleSeason({ id:docSnap.id, ...docSnap.data() }, nickname, user.uid)).filter(Boolean).sort((a,b)=>SEASONS.indexOf(a.season)-SEASONS.indexOf(b.season));
      const ratings = ratingSnapshot.docs.map(docSnap => ({ id:docSnap.id, ...docSnap.data() }));
      const reminders = reminderSnapshot ? reminderSnapshot.docs.map(docSnap => ({ id:docSnap.id, ...docSnap.data() })).filter(row => row.eventType === 'season-reminder' && !row.acknowledged) : [];
      lastData = { uid:String(user.uid), nickname, nicknameKey, seasons, ratings, reminders };
      loadedForUid = user.uid;
      updateNoticeBadge(lastData);
      return lastData;
    } finally {
      loading = false;
    }
  }

  function progress(data, season) {
    const ids = new Set((season.selectedOpeningIds || []).map(String));
    const done = new Set(data.ratings.filter(row => String(row.seasonKey || '') === String(season.key) && ids.has(String(row.openingId || '')) && Number.isFinite(Number(row.score))).map(row => String(row.openingId)));
    return { done:done.size, total:ids.size, complete:ids.size>0 && done.size>=ids.size };
  }

  function pendingSeasons(data) {
    if (!data) return [];
    return data.seasons.filter(season => {
      const state = progress(data, season);
      return state.total > state.done;
    });
  }

  function activeReminders(data) {
    if (!data) return [];
    const pending = pendingSeasons(data);
    const pendingKeys = new Set(pending.map(season => String(season.key)));
    const pendingNames = new Set(pending.map(season => String(season.season || '')));
    return data.reminders.filter(row => {
      const seasonKey = String(row.seasonKey || '');
      if (seasonKey) return pendingKeys.has(seasonKey);
      const season = String(row.season || '');
      return Boolean(season && pendingNames.has(season));
    });
  }

  function noticeCount(data) {
    if (!data) return 0;
    const seen = seenAssignments(data.uid);
    const assignments = pendingSeasons(data).filter(row => !seen.has(String(row.key))).length;
    return assignments + activeReminders(data).length;
  }

  function updateNoticeBadge(data) {
    const count = noticeCount(data);
    const button = tab();
    if (button) {
      button.classList.toggle('oc-my-events-has-notice', count > 0);
      button.dataset.noticeCount = count ? String(count) : '';
    }
    const notificationBell = bell();
    if (notificationBell) {
      notificationBell.classList.toggle('oc-event-notice', count > 0);
      notificationBell.dataset.eventNoticeCount = count ? String(count) : '';
      if (count > 0) notificationBell.title = `Есть уведомления по ивентам: ${count}`;
      else if (notificationBell.title?.startsWith('Есть уведомления по ивентам')) notificationBell.removeAttribute('title');
    }
  }

  function ownProfileSelected(data) {
    const selected = clean(document.querySelector('#oc-profile-user')?.value);
    return !selected || norm(selected) === norm(data?.nickname);
  }

  function openMyEvents() {
    const profileButton = document.querySelector('.oc-tab-btn[data-tab="profile"]');
    if (profileButton && !profileButton.classList.contains('active')) profileButton.click();
    window.setTimeout(() => {
      const eventsTab = tab();
      if (eventsTab) {
        eventsTab.click();
        eventsTab.focus?.();
      }
    }, 0);
  }

  function render(data) {
    const panel = ensurePanel();
    if (!panel) return;
    if (!data) {
      panel.innerHTML = '<div class="oc-empty">Войди в зарегистрированный аккаунт, чтобы увидеть свои ивенты.</div>';
      return;
    }
    if (!ownProfileSelected(data)) {
      panel.innerHTML = '<div class="oc-empty">«Мои ивенты» показываются только для твоего собственного аккаунта.</div>';
      return;
    }

    const seasonCards = data.seasons.length ? data.seasons.map(season => {
      const p = progress(data, season);
      const unseen = !seenAssignments(data.uid).has(String(season.key));
      return `<article class="oc-my-events-season ${p.complete?'complete':''} ${unseen?'unseen':''}"><div class="oc-my-events-season-top"><div><span>${esc(SEASON_LABEL[season.season] || season.season)} ${season.year}</span><strong>${p.done}/${p.total} оценено${p.complete?' ✓':''}</strong></div><span class="oc-my-events-linked">аккаунт ✓</span></div><div class="oc-my-events-progress"><span style="width:${p.total?Math.round(p.done/p.total*100):0}%"></span></div><p>${p.complete?'Сезон полностью оценён.':`Осталось ${Math.max(0,p.total-p.done)} OP · строка участника ${season.slot}.`}</p><a href="events.html?season=${encodeURIComponent(season.season)}" data-my-events-open-season="${esc(season.key)}">${p.done ? 'Продолжить оценивание' : 'Начать оценку'}</a></article>`;
    }).join('') : '<div class="oc-empty">Сейчас твой ник не указан ни в одном открытом сезоне.</div>';

    const reminders = activeReminders(data);
    const reminderHtml = reminders.length ? `<section class="oc-my-events-reminders"><h3>Напоминания</h3>${reminders.map(row => `<div><strong>${esc(row.seasonLabel || SEASON_LABEL[row.season] || 'Сезон')}</strong><span>${esc(row.message || 'Есть незавершённые оценки.')}</span><a href="events.html?season=${encodeURIComponent(row.season || '')}">Открыть</a></div>`).join('')}</section>` : '';

    panel.innerHTML = `<div class="oc-my-events-head"><div><span>личный центр</span><h2>Мои ивенты</h2><p>${esc(data.nickname)} · сезоны и быстрый переход к игровым режимам.</p></div><a href="events.html">Открыть Events</a></div>${reminderHtml}<section class="oc-my-events-seasons"><h3>Сезонные оценки</h3><div class="oc-my-events-grid">${seasonCards}</div></section><section class="oc-my-events-games"><h3>Игровые режимы</h3><div><a href="events.html?full=1&mode=guess">Угадайка</a><a href="events.html?full=1&mode=bestworst">Лучшее / Худшее</a><a href="events.html?full=1&mode=codenames">Codenames</a><a href="events.html?full=1&mode=blindtier">Слепой тир-лист</a><a href="events.html?full=1&mode=whoami">Кто я?</a><a href="events.html?full=1&mode=predictions">Предикты</a></div></section>`;
    panel.querySelectorAll('[data-my-events-open-season]').forEach(link => link.addEventListener('click', () => markSeen(data.uid, link.dataset.myEventsOpenSeason)));
  }

  async function refresh(force = false) {
    try {
      const data = await loadData(force);
      updateNoticeBadge(data);
      if (root()?.dataset.profileView === 'events') render(data);
    } catch (error) {
      console.warn('My Events profile load failed', error);
      if (root()?.dataset.profileView === 'events') ensurePanel().innerHTML = '<div class="oc-empty">Не удалось загрузить ивенты.</div>';
    }
  }

  function watchProfileView() {
    const profile = root();
    if (!profile) return;
    ensurePanel();
    new MutationObserver(() => {
      const panel = ensurePanel();
      panel?.classList.toggle('oc-profile-section-hidden', profile.dataset.profileView !== 'events');
      if (profile.dataset.profileView === 'events') void refresh(false);
    }).observe(profile, { attributes:true, attributeFilter:['data-profile-view'] });
    profile.querySelector('#oc-profile-user')?.addEventListener('change', () => { if (profile.dataset.profileView === 'events') render(lastData); });
  }

  function bindBell() {
    document.addEventListener('click', event => {
      const notificationBell = event.target.closest?.('#oc-daily-bell');
      if (!notificationBell || noticeCount(lastData) <= 0) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      openMyEvents();
    }, true);
  }

  function init() {
    watchProfileView();
    bindBell();
    window.setTimeout(() => void refresh(false), 800);
    window.addEventListener('oped-account-restored', () => { loadedForUid=''; lastData=null; void refresh(true); });
    window.addEventListener('storage', event => { if (event.key?.startsWith(ASSIGNMENT_SEEN_PREFIX)) updateNoticeBadge(lastData); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once:true });
  else init();
})();

/* deep-links.js */
(() => {
  if (window.__OC_DEEP_LINKS_READY__) return;

  const VIEWS = new Set(['chart', 'profile', 'top100', 'season', 'tier', 'stats', 'entity-studios', 'entity-performers', 'entity-directors', 'entity-franchises']);
  const ENTITY_VIEWS = new Set(['entity-studios', 'entity-performers', 'entity-directors', 'entity-franchises']);
  const SEASONS = new Set(['winter', 'spring', 'summer', 'fall']);
  let applying = false;

  const sleep = ms => new Promise(resolve => window.setTimeout(resolve, ms));
  const normalize = value => String(value || '').trim().toLowerCase().replace(/ё/g, 'е');

  function currentUrl() {
    return new URL(window.location.href);
  }

  function writeUrl(patch, replace = false) {
    if (applying) return;
    const url = currentUrl();
    Object.entries(patch).forEach(([key, value]) => {
      if (value === null || value === undefined || value === '') url.searchParams.delete(key);
      else url.searchParams.set(key, String(value));
    });
    const next = `${url.pathname}${url.search}${url.hash}`;
    window.history[replace ? 'replaceState' : 'pushState']({}, '', next);
  }

  function dispatchValue(element, inputToo = false) {
    if (!element) return;
    if (inputToo) element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
  }

  async function waitUntil(getter, timeout = 4500, interval = 70) {
    const started = Date.now();
    let value = getter();
    while (!value && Date.now() - started < timeout) {
      await sleep(interval);
      value = getter();
    }
    return value || null;
  }

  async function waitForAccountRestore(timeout = 8000) {
    if (window.__OC_ACCOUNT_RESTORE_DONE__) return;
    if (window.OC_ACCOUNT_READY && typeof window.OC_ACCOUNT_READY.then === 'function') {
      await Promise.race([window.OC_ACCOUNT_READY, sleep(timeout)]);
      return;
    }
    await Promise.race([
      new Promise(resolve => window.addEventListener('oped-account-restored', resolve, { once: true })),
      sleep(timeout)
    ]);
  }

  function tabButton(view) {
    return [...document.querySelectorAll('.oc-tab-btn[data-tab]')].find(button => button.dataset.tab === view) || null;
  }

  function clickTab(view) {
    const button = tabButton(view);
    if (!button) return false;
    button.click();
    return true;
  }

  function dataElement(attribute, value) {
    const wanted = normalize(value);
    return [...document.querySelectorAll(`[${attribute}]`)].find(element => normalize(element.getAttribute(attribute)) === wanted) || null;
  }

  function profileOption(select, value) {
    const wanted = normalize(value);
    return [...(select?.options || [])].find(option => normalize(option.value) === wanted || normalize(option.textContent) === wanted) || null;
  }

  async function applyProfile(url) {
    const profile = url.searchParams.get('profile');
    const section = url.searchParams.get('section');
    const select = await waitUntil(() => document.querySelector('#oc-profile-user'), 3000);
    if (profile && select) {
      const option = await waitUntil(() => profileOption(select, profile), 4000);
      if (option) {
        select.value = option.value;
        dispatchValue(select);
      }
    }
    if (section) {
      const subtab = await waitUntil(() => [...document.querySelectorAll('[data-profile-view]')].find(button => button.dataset.profileView === section), 1800);
      subtab?.click();
    }
  }

  async function applySeason(url) {
    const type = String(url.searchParams.get('type') || '').toUpperCase();
    const year = String(url.searchParams.get('year') || '').trim();
    const season = String(url.searchParams.get('season') || '').toLowerCase();

    if (type === 'OP' || type === 'ED') {
      dataElement('data-season-type', type)?.click();
    }
    if (!year) return;

    const yearButton = await waitUntil(() => dataElement('data-season-year', year), 4500);
    yearButton?.click();
    if (!SEASONS.has(season)) return;

    const seasonButton = await waitUntil(() => [...document.querySelectorAll('[data-season-select]')].find(button => String(button.dataset.year || '') === year && String(button.dataset.season || '') === season), 3500);
    seasonButton?.click();
  }

  async function applyEntity(url, view) {
    const type = view.replace('entity-', '');
    const home = await waitUntil(() => dataElement('data-entity-home', type), 3000);
    home?.click();

    const album = url.searchParams.get('album');
    if (!album) return;
    const card = await waitUntil(() => dataElement('data-entity-open', album), 4500);
    card?.click();
  }

  async function exactTrackTitle(id) {
    try {
      if (!window.OPED_DB) {
        await new Promise(resolve => {
          const timer = window.setTimeout(resolve, 5000);
          window.addEventListener('oped-db-ready', () => {
            window.clearTimeout(timer);
            resolve();
          }, { once: true });
        });
      }
      const [{ getApp, getApps }, { getFirestore, doc, getDoc }] = await Promise.all([
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js')
      ]);
      if (!getApps().length) return '';
      const snapshot = await getDoc(doc(getFirestore(getApp()), 'openings', String(id)));
      return snapshot.exists() ? String(snapshot.data()?.title || '').trim() : '';
    } catch (error) {
      console.warn('Deep link track lookup failed', error);
      return '';
    }
  }

  function trackCard(id) {
    return [...document.querySelectorAll('.oc-unified-card[data-id]')].find(card => String(card.dataset.id || '') === String(id)) || null;
  }

  async function applyTrack(id) {
    const trackId = String(id || '').trim();
    if (!trackId) return false;
    clickTab('chart');

    let card = trackCard(trackId);
    let previousSearch = null;
    const search = document.querySelector('#oc-f-search');

    if (!card) {
      const title = await exactTrackTitle(trackId);
      if (title && search) {
        previousSearch = search.value;
        search.value = title;
        dispatchValue(search, true);
        card = await waitUntil(() => trackCard(trackId), 3500);
      }
    }

    const openButton = card?.querySelector('[data-action="open-card"]');
    if (openButton) {
      openButton.click();
      await sleep(80);
    }

    if (previousSearch !== null && search) {
      search.value = previousSearch;
      dispatchValue(search, true);
    }
    return Boolean(openButton);
  }

  function closeTrackModal() {
    const modal = document.querySelector('#oc-opening-modal');
    if (!modal || modal.classList.contains('hidden')) return;
    const close = modal.querySelector('[data-modal-close],[data-action="close"],[data-action="close-modal"],.oc-modal-close,button[aria-label="Закрыть"]');
    if (close) close.click();
    else modal.classList.add('hidden');
  }

  async function applyUrl() {
    if (applying) return;
    applying = true;
    try {
      await waitForAccountRestore();
      const url = currentUrl();
      const track = url.searchParams.get('track');
      let view = url.searchParams.get('view') || 'chart';
      if (!VIEWS.has(view)) view = 'chart';
      if (track) view = 'chart';

      if (ENTITY_VIEWS.has(view)) await applyEntity(url, view);
      else clickTab(view);

      if (view === 'profile') await applyProfile(url);
      if (view === 'season') await applySeason(url);
      if (track) await applyTrack(track);
      else closeTrackModal();
    } finally {
      applying = false;
    }
  }

  function currentEntityView() {
    const fromUrl = currentUrl().searchParams.get('view');
    if (ENTITY_VIEWS.has(fromUrl)) return fromUrl;
    const active = [...document.querySelectorAll('[data-entity-home]')].find(element => element.classList.contains('active'));
    return active ? `entity-${active.dataset.entityHome}` : '';
  }

  function bindUrlUpdates() {
    document.addEventListener('click', event => {
      if (applying) return;

      const tab = event.target.closest('.oc-tab-btn[data-tab]');
      if (tab) {
        const view = tab.dataset.tab;
        writeUrl({
          view: view === 'chart' ? null : view,
          profile: view === 'profile' ? document.querySelector('#oc-profile-user')?.value || null : null,
          section: view === 'profile' ? document.querySelector('[data-profile-view].active')?.dataset.profileView || null : null,
          year: view === 'season' ? currentUrl().searchParams.get('year') : null,
          season: view === 'season' ? currentUrl().searchParams.get('season') : null,
          type: view === 'season' ? currentUrl().searchParams.get('type') : null,
          album: null,
          track: null
        });
        return;
      }

      const entityHome = event.target.closest('[data-entity-home]');
      if (entityHome) {
        writeUrl({ view: `entity-${entityHome.dataset.entityHome}`, album: null, track: null, profile: null, section: null, year: null, season: null, type: null });
        return;
      }

      const album = event.target.closest('[data-entity-open]');
      if (album) {
        writeUrl({ view: currentEntityView() || null, album: album.dataset.entityOpen || null, track: null });
        return;
      }

      const openCard = event.target.closest('[data-action="open-card"]');
      if (openCard) {
        const id = String(openCard.dataset.id || openCard.closest('[data-id]')?.dataset.id || '').trim();
        if (id) writeUrl({ view: null, track: id, album: null });
        return;
      }

      const profileSection = event.target.closest('[data-profile-view]');
      if (profileSection && !document.querySelector('#oc-profile-panel')?.classList.contains('hidden')) {
        writeUrl({ view: 'profile', section: profileSection.dataset.profileView || null, profile: document.querySelector('#oc-profile-user')?.value || null });
        return;
      }

      const seasonYear = event.target.closest('[data-season-year]');
      if (seasonYear) {
        writeUrl({ view: 'season', year: seasonYear.dataset.seasonYear || null, track: null });
        return;
      }

      const season = event.target.closest('[data-season-select]');
      if (season) {
        writeUrl({ view: 'season', year: season.dataset.year || null, season: season.dataset.season || null, track: null });
        return;
      }

      const seasonType = event.target.closest('[data-season-type]');
      if (seasonType) {
        writeUrl({ view: 'season', type: seasonType.dataset.seasonType || null, track: null });
        return;
      }

      const modal = document.querySelector('#oc-opening-modal');
      const modalClose = event.target.closest('[data-modal-close],[data-action="close"],[data-action="close-modal"],.oc-modal-close,button[aria-label="Закрыть"]');
      if (modalClose && modal?.contains(modalClose)) writeUrl({ track: null }, true);
    }, true);

    document.addEventListener('change', event => {
      if (applying) return;
      if (event.target?.id === 'oc-profile-user' && !document.querySelector('#oc-profile-panel')?.classList.contains('hidden')) {
        writeUrl({ view: 'profile', profile: event.target.value || null }, true);
      }
    }, true);

    window.addEventListener('popstate', () => { void applyUrl(); });
  }

  function init() {
    if (window.__OC_DEEP_LINKS_READY__) return;
    bindUrlUpdates();
    window.__OC_DEEP_LINKS_READY__ = true;
    window.setTimeout(() => { void applyUrl(); }, 120);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();

/* quality-center.js */
(() => {
  if (window.__OC_QUALITY_CENTER_READY__) return;

  const SEASON_LABEL = { winter: 'Зима', spring: 'Весна', summer: 'Лето', fall: 'Осень' };
  const ISSUE_LIMIT = 40;
  let modal = null;
  let cachedOpenings = null;
  let loadingPromise = null;
  let triggerButton = null;
  let currentIssues = new Map();

  const normalize = value => String(value || '').trim().toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ');
  const cleanList = value => Array.isArray(value) ? value.filter(item => String(item || '').trim()).length : String(value || '').split(',').filter(item => item.trim()).length;

  function escapeHtml(value) {
    return String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
  }

  function isAdminUi() {
    return normalize(document.querySelector('#oc-access-badge')?.textContent).includes('админ');
  }

  function yieldToUi() {
    return new Promise(resolve => requestAnimationFrame(() => window.setTimeout(resolve, 0)));
  }

  async function waitForFirebase() {
    if (window.OPED_DB) return;
    await new Promise(resolve => {
      const timer = window.setTimeout(resolve, 5000);
      window.addEventListener('oped-db-ready', () => {
        window.clearTimeout(timer);
        resolve();
      }, { once: true });
    });
  }

  async function loadOpenings(force = false) {
    if (!force && cachedOpenings) return cachedOpenings;
    if (!force && loadingPromise) return loadingPromise;

    loadingPromise = (async () => {
      await waitForFirebase();
      const [{ getApp, getApps }, { getFirestore, collection, getDocs }] = await Promise.all([
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js')
      ]);
      if (!getApps().length) throw new Error('Firebase ещё не инициализирован.');
      const snapshot = await getDocs(collection(getFirestore(getApp()), 'openings'));
      cachedOpenings = snapshot.docs.map(documentSnapshot => ({ id: documentSnapshot.id, ...documentSnapshot.data() }));
      return cachedOpenings;
    })();

    try {
      return await loadingPromise;
    } finally {
      loadingPromise = null;
    }
  }

  function buildIssues(openings) {
    const issues = [
      { id: 'title', label: 'Без названия', rows: [] },
      { id: 'image', label: 'Без основной картинки', rows: [] },
      { id: 'fallback', label: 'Без запасной картинки', rows: [] },
      { id: 'performer', label: 'Без исполнителя', rows: [] },
      { id: 'studio', label: 'Без студии', rows: [] },
      { id: 'director', label: 'Без режиссёра', rows: [] },
      { id: 'franchise', label: 'Без франшизы', rows: [] },
      { id: 'link', label: 'Без ссылки на видео', rows: [] },
      { id: 'same-song', label: 'Одинаковая песня без группы', rows: [] },
      { id: 'duplicate', label: 'Возможные дубликаты', rows: [] }
    ];
    const byId = new Map(issues.map(issue => [issue.id, issue]));
    const duplicateMap = new Map();

    for (const opening of openings) {
      const rawTitle = String(opening.title || opening.anime || '').trim();
      if (!rawTitle) byId.get('title').rows.push(opening);
      if (!String(opening.image || '').trim()) byId.get('image').rows.push(opening);
      if (!String(opening.fallbackImage || opening.imageFallback || '').trim()) byId.get('fallback').rows.push(opening);
      if (!cleanList(opening.performers)) byId.get('performer').rows.push(opening);
      if (!cleanList(opening.studios)) byId.get('studio').rows.push(opening);
      if (!cleanList(opening.directors)) byId.get('director').rows.push(opening);
      if (!cleanList(opening.franchises)) byId.get('franchise').rows.push(opening);
      if (!String(opening.link || '').trim()) byId.get('link').rows.push(opening);
      if (String(opening.sameSongTitle || opening.songGroupTitle || '').trim() && !String(opening.sameSongGroupId || opening.songGroupId || '').trim()) byId.get('same-song').rows.push(opening);

      const title = normalize(rawTitle);
      if (title) {
        const key = `${title}|${String(opening.type || '')}|${String(opening.year || '')}|${String(opening.season || '')}`;
        const group = duplicateMap.get(key);
        if (group) group.push(opening);
        else duplicateMap.set(key, [opening]);
      }
    }

    for (const group of duplicateMap.values()) {
      if (group.length > 1) byId.get('duplicate').rows.push(...group);
    }
    return issues;
  }

  function completeness(openings, issues) {
    if (!openings.length) return 100;
    const keyIds = new Set(['image', 'performer', 'studio', 'director', 'franchise', 'link']);
    let missing = 0;
    for (const issue of issues) if (keyIds.has(issue.id)) missing += issue.rows.length;
    return Math.max(0, Math.round((1 - missing / (openings.length * keyIds.size)) * 100));
  }

  function ensureModal() {
    if (modal?.isConnected) return modal;
    modal = document.createElement('div');
    modal.className = 'oc-quality-modal hidden';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-label', 'Центр качества базы');
    document.body.append(modal);

    modal.addEventListener('click', event => {
      if (event.target === modal || event.target.closest('[data-quality-close]')) {
        closeQualityCenter();
        return;
      }

      const refresh = event.target.closest('[data-quality-refresh]');
      if (refresh) {
        void openQualityCenter(true);
        return;
      }

      const summary = event.target.closest('.oc-quality-issue > summary');
      if (summary) {
        const details = summary.parentElement;
        window.setTimeout(() => {
          if (details?.open) renderIssueRows(details);
        }, 0);
        return;
      }

      const track = event.target.closest('[data-quality-track]');
      if (track) openTrack(String(track.dataset.qualityTrack || ''), String(track.dataset.qualityTitle || ''));
    });

    return modal;
  }

  function renderIssueRows(details) {
    if (!details || details.dataset.qualityRendered === '1') return;
    const issue = currentIssues.get(details.dataset.qualityIssue || '');
    const list = details.querySelector('.oc-quality-track-list');
    if (!issue || !list) return;

    details.dataset.qualityRendered = '1';
    if (!issue.rows.length) {
      list.innerHTML = '<div class="oc-quality-ok">Проблем не найдено ✓</div>';
      return;
    }

    const visibleRows = issue.rows.slice(0, ISSUE_LIMIT);
    list.innerHTML = visibleRows.map(opening => {
      const season = opening.season ? `${SEASON_LABEL[opening.season] || opening.season} ${opening.year || ''}`.trim() : String(opening.year || '—');
      const title = String(opening.title || opening.anime || 'Без названия');
      return `<button type="button" class="oc-quality-track" data-quality-track="${escapeHtml(opening.id)}" data-quality-title="${escapeHtml(title)}"><span>${escapeHtml(title)}</span><small>${escapeHtml(opening.type || '—')} · ${escapeHtml(season)}</small></button>`;
    }).join('') + (issue.rows.length > visibleRows.length ? `<div class="oc-quality-more">Показаны первые ${visibleRows.length} из ${issue.rows.length}</div>` : '');
  }

  function renderLoading() {
    const root = ensureModal();
    currentIssues = new Map();
    root.innerHTML = `
      <div class="oc-quality-dialog">
        <div class="oc-quality-head">
          <div>
            <div class="oc-quality-kicker">админ · качество базы</div>
            <h2>Центр качества</h2>
            <p>Проверяю только коллекцию треков. Оценки и другие большие коллекции не загружаются.</p>
          </div>
          <button class="oc-quality-close" type="button" data-quality-close aria-label="Закрыть">×</button>
        </div>
        <div class="oc-quality-loading">Проверяю каталог…</div>
      </div>`;
  }

  function renderError(error) {
    const root = ensureModal();
    currentIssues = new Map();
    root.innerHTML = `
      <div class="oc-quality-dialog">
        <div class="oc-quality-head">
          <div><div class="oc-quality-kicker">админ · качество базы</div><h2>Центр качества</h2><p>Не удалось получить каталог.</p></div>
          <button class="oc-quality-close" type="button" data-quality-close aria-label="Закрыть">×</button>
        </div>
        <div class="oc-quality-error">${escapeHtml(error?.message || 'Неизвестная ошибка')}</div>
        <button class="oc-quality-refresh" type="button" data-quality-refresh>Попробовать ещё раз</button>
      </div>`;
  }

  function render(openings) {
    const root = ensureModal();
    const issues = buildIssues(openings);
    currentIssues = new Map(issues.map(issue => [issue.id, issue]));
    const score = completeness(openings, issues);
    const uniqueProblemIds = new Set();
    let totalHits = 0;
    for (const issue of issues) {
      totalHits += issue.rows.length;
      for (const opening of issue.rows) uniqueProblemIds.add(String(opening.id));
    }

    const issueHtml = issues.map(issue => `
      <details class="oc-quality-issue" data-quality-issue="${issue.id}">
        <summary><span>${escapeHtml(issue.label)}</span><strong>${issue.rows.length}</strong></summary>
        <div class="oc-quality-track-list"><div class="oc-quality-more">Список загрузится при открытии раздела</div></div>
      </details>`).join('');

    root.innerHTML = `
      <div class="oc-quality-dialog">
        <div class="oc-quality-head">
          <div>
            <div class="oc-quality-kicker">админ · качество базы</div>
            <h2>Центр качества</h2>
            <p>Пустые поля, одинаковая песня без группы и возможные дубликаты. Списки треков создаются только когда ты раскрываешь нужный раздел.</p>
          </div>
          <div class="oc-quality-head-actions">
            <button class="oc-quality-refresh" type="button" data-quality-refresh>Обновить</button>
            <button class="oc-quality-close" type="button" data-quality-close aria-label="Закрыть">×</button>
          </div>
        </div>
        <div class="oc-quality-summary">
          <div><strong>${openings.length}</strong><span>треков</span></div>
          <div><strong>${score}%</strong><span>ключевые поля</span></div>
          <div><strong>${uniqueProblemIds.size}</strong><span>треков с проблемами</span></div>
          <div><strong>${totalHits}</strong><span>срабатываний</span></div>
        </div>
        <div class="oc-quality-issues">${issueHtml}</div>
      </div>`;
  }

  function fallbackOpenTrack(title) {
    document.querySelector('.oc-tab-btn[data-tab="chart"]')?.click();
    document.querySelector('#oc-reset-filters')?.click();
    window.setTimeout(() => {
      const search = document.querySelector('#oc-f-search');
      if (!search) return;
      search.value = title;
      search.dispatchEvent(new Event('input', { bubbles: true }));
      search.dispatchEvent(new Event('change', { bubbles: true }));
      search.focus();
    }, 0);
  }

  function openTrack(id, title) {
    closeQualityCenter();
    if (window.__OC_DEEP_LINKS_READY__ && id) {
      const url = new URL(window.location.href);
      ['view', 'profile', 'section', 'album'].forEach(key => url.searchParams.delete(key));
      url.searchParams.set('track', id);
      history.pushState({}, '', `${url.pathname}${url.search}${url.hash}`);
      window.dispatchEvent(new PopStateEvent('popstate'));
      return;
    }
    fallbackOpenTrack(title);
  }

  async function openQualityCenter(force = false) {
    if (!isAdminUi()) return;
    const root = ensureModal();
    root.classList.remove('hidden');
    document.body.classList.add('oc-quality-open');
    renderLoading();

    try {
      await yieldToUi();
      const openings = await loadOpenings(force);
      if (root.classList.contains('hidden')) return;
      await yieldToUi();
      render(openings);
    } catch (error) {
      console.error('Quality center load failed', error);
      if (!root.classList.contains('hidden')) renderError(error);
    }
  }

  function closeQualityCenter() {
    if (!modal) return;
    modal.classList.add('hidden');
    document.body.classList.remove('oc-quality-open');
  }

  function syncTriggerVisibility() {
    if (triggerButton) triggerButton.hidden = !isAdminUi();
  }

  function mountTrigger(attempt = 0) {
    if (triggerButton?.isConnected) return;
    const host = document.querySelector('.oc-topbar-admin');
    if (!host) {
      if (attempt < 40) window.setTimeout(() => mountTrigger(attempt + 1), 100);
      return;
    }

    triggerButton = document.createElement('button');
    triggerButton.id = 'oc-quality-center-btn';
    triggerButton.className = 'oc-franchise-repair-btn oc-quality-trigger';
    triggerButton.type = 'button';
    triggerButton.textContent = 'Центр качества базы';
    triggerButton.addEventListener('click', () => { void openQualityCenter(false); });
    host.append(triggerButton);
    syncTriggerVisibility();

    const badge = document.querySelector('#oc-access-badge');
    if (badge) new MutationObserver(syncTriggerVisibility).observe(badge, { childList: true, characterData: true, subtree: true });
  }

  window.addEventListener('oped-open-quality', () => { void openQualityCenter(false); });
  window.__OC_QUALITY_CENTER_READY__ = true;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => mountTrigger(), { once: true });
  else mountTrigger();
})();

/* quality-center-user-route.js */
(() => {
  if (window.__OC_QUALITY_CENTER_USER_ROUTE_READY__) return;
  window.__OC_QUALITY_CENTER_USER_ROUTE_READY__ = true;

  const RICKROLL_URL = 'https://www.youtube.com/watch?v=dQw4w9WgXcQ';

  function isAdminUi() {
    const badge = document.querySelector('#oc-access-badge');
    return Boolean(badge && badge.classList.contains('admin') && String(badge.textContent || '').trim().toLocaleLowerCase('ru') === 'админ');
  }

  function syncButton() {
    const button = document.querySelector('.oc-quality-trigger');
    if (!button) return;
    button.hidden = false;
    button.title = 'Центр качества базы';
  }

  document.addEventListener('click', event => {
    const button = event.target.closest?.('.oc-quality-trigger');
    if (!button || isAdminUi()) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    window.location.assign(RICKROLL_URL);
  }, true);

  const root = document.querySelector('#opedchart-root') || document.documentElement;
  new MutationObserver(syncButton).observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ['hidden', 'class'] });
  [0, 100, 400, 1200, 3000].forEach(delay => window.setTimeout(syncButton, delay));
})();

/* keyboard-shortcuts.js */
(() => {
  if (window.__OC_KEYBOARD_SHORTCUTS_READY__) return;

  let help = null;
  let loginAttemptSerial = 0;
  let lastLoginAttemptAt = 0;

  function isEditable(target) {
    return Boolean(target?.closest?.('input,textarea,select,[contenteditable="true"]'));
  }

  function visible(selector) {
    return [...document.querySelectorAll(selector)].find(element => !element.classList.contains('hidden') && element.getClientRects().length) || null;
  }

  function ensureHelp() {
    if (help?.isConnected) return help;
    help = document.createElement('div');
    help.className = 'oc-hotkeys-help hidden';
    help.innerHTML = `
      <div class="oc-hotkeys-card" role="dialog" aria-modal="true" aria-label="Горячие клавиши">
        <div class="oc-hotkeys-head"><div><span>быстрое управление</span><h2>Горячие клавиши</h2></div><button type="button" data-hotkeys-close aria-label="Закрыть">×</button></div>
        <div class="oc-hotkeys-grid">
          <div><kbd>.</kbd><span>Перейти к поиску</span></div>
          <div><kbd>Пробел</kbd><span>Запустить видео в открытой карточке</span></div>
          <div><kbd>Esc</kbd><span>Закрыть карточку или отменить её редактирование</span></div>
          <div><kbd>?</kbd><span>Снова открыть этот гайд</span></div>
        </div>
      </div>`;
    document.body.append(help);
    help.addEventListener('click', event => {
      if (event.target === help || event.target.closest('[data-hotkeys-close]')) hideHelp();
    });
    return help;
  }

  function showHelp() {
    ensureHelp().classList.remove('hidden');
    help.querySelector('[data-hotkeys-close]')?.focus();
  }

  function hideHelp() {
    help?.classList.add('hidden');
  }

  function closeTopModal() {
    if (help && !help.classList.contains('hidden')) {
      hideHelp();
      return true;
    }

    const modal = visible('.oc-quality-modal,#oc-opening-modal,#oc-season-evaluator,#oc-auth-modal,#oc-register-modal,#oc-name-modal,#oc-confirm-modal,#oc-franchise-repair-modal,#oc-image-migration-modal');
    if (!modal) return false;

    const close = modal.querySelector('[data-quality-close],[data-modal-close],[data-eval-action="close"],#oc-auth-close,#oc-register-close,#oc-modal-name-close,[data-image-migration-close],[data-action="close"],[data-action="close-modal"],.oc-modal-close,.oc-edit-cancel,button[aria-label="Закрыть"]');
    if (close) close.click();
    else modal.classList.add('hidden');
    return true;
  }

  function cancelTrackEdit() {
    const editCard = visible('.oc-editcard');
    if (!editCard) return false;
    const cancel = editCard.querySelector('[data-action="cancel-edit"]');
    if (!cancel) return false;
    cancel.click();
    return true;
  }

  function closeMenus() {
    let changed = false;
    document.querySelectorAll('.oc-topbar-account[open],.oc-topbar-ratings[open]').forEach(details => {
      details.open = false;
      changed = true;
    });
    document.querySelectorAll('.oc-topbar-mobile-ratings-menu').forEach(menu => {
      if (!menu.hidden) {
        menu.hidden = true;
        changed = true;
      }
    });
    return changed;
  }

  function focusSearch() {
    const profileVisible = !document.querySelector('#oc-profile-panel')?.classList.contains('hidden');
    const mainVisible = !document.querySelector('#oc-main-panel')?.classList.contains('hidden');
    const search = document.querySelector(profileVisible ? '#oc-p-search' : '#oc-f-search');
    if (!search) return false;

    if (!mainVisible && !profileVisible) document.querySelector('.oc-tab-btn[data-tab="chart"]')?.click();
    window.setTimeout(() => {
      search.focus();
      search.select?.();
    }, 0);
    return true;
  }

  function handleCardVideo() {
    const opening = visible('#oc-opening-modal');
    if (!opening) return false;

    const directVideo = opening.querySelector('.oc-video-frame video');
    if (directVideo) {
      if (directVideo.paused) directVideo.play().catch(() => {});
      else directVideo.pause();
      return true;
    }

    const cover = opening.querySelector('.oc-video-cover');
    if (cover) {
      cover.click();
      return true;
    }

    return false;
  }

  function currentPersonalUid() {
    try {
      return String(window.OPED_DB?.currentUserUid?.() || '');
    } catch (error) {
      return '';
    }
  }

  function markLoginAttempt() {
    loginAttemptSerial += 1;
    lastLoginAttemptAt = Date.now();
  }

  function watchLoginModal(modal) {
    if (!modal) return;
    let wasOpen = !modal.classList.contains('hidden');
    let uidWhenOpened = wasOpen ? currentPersonalUid() : '';
    let attemptWhenOpened = loginAttemptSerial;

    new MutationObserver(() => {
      const isOpen = !modal.classList.contains('hidden');
      if (isOpen && !wasOpen) {
        uidWhenOpened = currentPersonalUid();
        attemptWhenOpened = loginAttemptSerial;
      }
      if (!isOpen && wasOpen) {
        const hadExplicitLogin = loginAttemptSerial > attemptWhenOpened && Date.now() - lastLoginAttemptAt < 15000;
        window.setTimeout(() => {
          const uidAfter = currentPersonalUid();
          if (hadExplicitLogin && uidAfter && uidAfter !== uidWhenOpened) showHelp();
        }, 120);
      }
      wasOpen = isOpen;
    }).observe(modal, { attributes: true, attributeFilter: ['class'] });
  }

  function bindLoginGuide() {
    document.addEventListener('pointerdown', event => {
      if (event.target?.closest?.('#oc-auth-save,#oc-modal-name-save')) markLoginAttempt();
    }, true);
    document.addEventListener('keydown', event => {
      if (event.key === 'Enter' && event.target?.closest?.('#oc-auth-modal,#oc-name-modal')) markLoginAttempt();
    }, true);
    watchLoginModal(document.querySelector('#oc-auth-modal'));
    watchLoginModal(document.querySelector('#oc-name-modal'));
  }

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      if (closeTopModal() || cancelTrackEdit() || closeMenus()) event.preventDefault();
      return;
    }

    if (isEditable(event.target)) return;

    if (event.key === '.' || event.code === 'Period') {
      if (focusSearch()) event.preventDefault();
      return;
    }

    if (event.key === ' ' || event.code === 'Space') {
      if (handleCardVideo()) event.preventDefault();
      return;
    }

    if (event.key === '?') {
      showHelp();
      event.preventDefault();
    }
  });

  window.__OC_KEYBOARD_SHORTCUTS_READY__ = true;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bindLoginGuide, { once: true });
  else bindLoginGuide();
})();

/* toast.js */
(() => {
  if (window.OC_TOAST) return;

  let stack = null;
  let lastMessage = '';
  let lastShownAt = 0;

  function ensureStack() {
    if (stack?.isConnected) return stack;
    stack = document.createElement('div');
    stack.className = 'oc-toast-stack';
    stack.setAttribute('aria-live', 'polite');
    stack.setAttribute('aria-atomic', 'false');
    document.body.append(stack);
    return stack;
  }

  function removeToast(node) {
    if (!node?.isConnected) return;
    node.classList.add('out');
    window.setTimeout(() => node.remove(), 180);
  }

  function show(message, options = {}) {
    const text = String(message || '').trim();
    if (!text) return null;
    const now = Date.now();
    if (!options.force && text === lastMessage && now - lastShownAt < 700) return null;
    lastMessage = text;
    lastShownAt = now;

    const node = document.createElement('div');
    node.className = `oc-toast ${options.type || ''}`.trim();
    node.setAttribute('role', options.type === 'error' ? 'alert' : 'status');

    const messageEl = document.createElement('div');
    messageEl.className = 'oc-toast-message';
    messageEl.textContent = text;
    node.append(messageEl);

    const actions = document.createElement('div');
    actions.className = 'oc-toast-actions';
    if (options.actionLabel && typeof options.onAction === 'function') {
      const action = document.createElement('button');
      action.type = 'button';
      action.textContent = options.actionLabel;
      action.addEventListener('click', async () => {
        action.disabled = true;
        try { await options.onAction(); }
        finally { removeToast(node); }
      }, { once: true });
      actions.append(action);
    }
    const close = document.createElement('button');
    close.type = 'button';
    close.setAttribute('aria-label', 'Закрыть уведомление');
    close.textContent = '×';
    close.addEventListener('click', () => removeToast(node), { once: true });
    actions.append(close);
    node.append(actions);

    ensureStack().append(node);
    const lifetime = Number(options.duration || (options.actionLabel ? 8000 : 3600));
    if (lifetime > 0) window.setTimeout(() => removeToast(node), lifetime);
    return node;
  }

  function bindLegacyStatus(attempt = 0) {
    const status = document.querySelector('#oc-status');
    if (!status) {
      if (attempt < 30) window.setTimeout(() => bindLegacyStatus(attempt + 1), 100);
      return;
    }
    status.setAttribute('aria-live', 'polite');
    let previous = String(status.textContent || '').trim();
    new MutationObserver(() => {
      const text = String(status.textContent || '').trim();
      if (!text || text === previous) return;
      previous = text;
      const style = String(status.style?.color || '').toLowerCase();
      const error = style.includes('255') || /не удалось|ошиб|нельзя|нужен/i.test(text);
      show(text, { type: error ? 'error' : (/✓|сохран|готов|выполн/i.test(text) ? 'success' : '') });
    }).observe(status, { childList: true, characterData: true, subtree: true });
  }

  window.OC_TOAST = { show };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => bindLegacyStatus(), { once: true });
  else bindLegacyStatus();
})();

/* skeleton-loading.js */
(() => {
  if (window.__OC_SKELETON_LOADING_READY__) return;

  const skeletonHtml = count => `<div class="oc-skeleton-list" aria-hidden="true">${Array.from({ length: count }, () => `
    <div class="oc-skeleton-card">
      <div class="oc-skeleton-thumb"></div>
      <div class="oc-skeleton-body">
        <div class="oc-skeleton-line w70"></div>
        <div class="oc-skeleton-line w45"></div>
        <div class="oc-skeleton-pills"><div class="oc-skeleton-pill"></div><div class="oc-skeleton-pill"></div><div class="oc-skeleton-pill"></div></div>
      </div>
    </div>`).join('')}</div>`;

  function showInitialCatalogSkeleton() {
    const container = document.querySelector('#oc-list-container');
    if (!container) return;
    const text = String(container.textContent || '').trim().toLowerCase();
    if (text.includes('загрузка списка')) container.innerHTML = skeletonHtml(6);
  }

  function showPanelSkeleton(panel) {
    if (!panel || panel.classList.contains('hidden')) return;
    const target = panel.querySelector('#oc-profile-op,#oc-top100-list,#oc-tier-list,.oc-profile-list,.oc-allratings-list');
    if (!target) return;
    const text = String(target.textContent || '').trim().toLowerCase();
    if (text.includes('загрузка')) target.innerHTML = skeletonHtml(3);
  }

  document.addEventListener('click', event => {
    const tab = event.target.closest('.oc-tab-btn[data-tab]');
    if (!tab) return;
    window.requestAnimationFrame(() => {
      const panel = document.querySelector(`#oc-${tab.dataset.tab}-panel`);
      showPanelSkeleton(panel);
    });
  }, true);

  window.__OC_SKELETON_LOADING_READY__ = true;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', showInitialCatalogSkeleton, { once: true });
  else showInitialCatalogSkeleton();
})();

/* advanced-filters.js */
(() => {
  if (window.__OC_ADVANCED_FILTERS_READY__) return;

  const STORAGE_KEY = 'oc-advanced-filters-open-v1';

  function savedState(scope) {
    try {
      const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      return Boolean(raw?.[scope]);
    } catch (_) {
      return false;
    }
  }

  function saveState(scope, open) {
    let raw = {};
    try { raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') || {}; } catch (_) {}
    raw[scope] = Boolean(open);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(raw));
  }

  function hasSelection(root) {
    return [...root.querySelectorAll('select[multiple]')].some(select => [...select.selectedOptions].some(option => String(option.value || '').trim()));
  }

  function removeMissingFieldsFilter() {
    const input = document.querySelector('#oc-f-missing');
    if (!input) return;
    if (input.checked) {
      input.checked = false;
      input.dispatchEvent(new Event('change', { bubbles: true }));
    }
    input.closest('.oc-field')?.remove();
  }

  function mount(scope, divider, advanced) {
    if (!divider || !advanced || divider.dataset.advancedMounted === '1') return;
    divider.dataset.advancedMounted = '1';
    divider.classList.add('oc-advanced-toggle-wrap');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'oc-advanced-toggle';
    button.innerHTML = '<span>Расширенные фильтры</span><span class="oc-advanced-toggle-arrow">⌄</span>';
    divider.replaceChildren(button);

    const setOpen = open => {
      const next = Boolean(open);
      button.setAttribute('aria-expanded', next ? 'true' : 'false');
      advanced.classList.toggle('oc-advanced-collapsed', !next);
      saveState(scope, next);
    };

    setOpen(savedState(scope) || hasSelection(advanced));
    button.addEventListener('click', () => setOpen(button.getAttribute('aria-expanded') !== 'true'));
    advanced.addEventListener('change', () => {
      if (hasSelection(advanced)) setOpen(true);
    });
  }

  function init(attempt = 0) {
    removeMissingFieldsFilter();

    const mainDivider = document.querySelector('#oc-main-panel .oc-filter-divider');
    const mainAdvanced = document.querySelector('#oc-main-panel .oc-filter-advanced');
    const profileDivider = document.querySelector('#oc-profile-panel .oc-profile-filter-divider');
    const profileAdvanced = document.querySelector('#oc-profile-panel .oc-profile-filter-advanced');

    mount('main', mainDivider, mainAdvanced);
    mount('profile', profileDivider, profileAdvanced);

    if ((!mainDivider || !profileDivider) && attempt < 30) window.setTimeout(() => init(attempt + 1), 100);
  }

  window.__OC_ADVANCED_FILTERS_READY__ = true;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => init(), { once: true });
  else init();
})();

/* undo-actions.js */
(() => {
  if (window.__OC_UNDO_ACTIONS_READY__) return;

  let lastOpenedTrackId = '';
  let firestorePromise = null;

  function nickname() {
    return String(localStorage.getItem('op-ed-primary-account-name') || '').trim();
  }

  async function firestore() {
    if (!firestorePromise) {
      firestorePromise = Promise.all([
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-app.js'),
        import('https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js')
      ]).then(([appApi, dbApi]) => {
        const app = appApi.getApps().length ? appApi.getApp() : null;
        if (!app) throw new Error('Firebase ещё не инициализирован.');
        return { ...dbApi, db: dbApi.getFirestore(app) };
      });
    }
    return firestorePromise;
  }

  function toast(message, options = {}) {
    if (window.OC_TOAST?.show) return window.OC_TOAST.show(message, options);
    return null;
  }

  function currentTrackId(button) {
    return String(button?.dataset?.id || new URL(location.href).searchParams.get('track') || lastOpenedTrackId || '').trim();
  }

  function ratingFields(button) {
    if (button.matches('[data-card-action="delete-rating"],[data-action="all-delete-rating"]')) return ['score', 'songScore', 'visualScore'];
    const slider = button.closest('.oc-unified-card,.oc-card,.oc-entry-card,article,div')?.querySelector?.('.oc-slider');
    const personal = /отметк|1\s*[–-]\s*5/i.test(button.textContent || '') || (slider && Number(slider.max) <= 5);
    return personal ? ['personalScore'] : ['score', 'songScore', 'visualScore'];
  }

  async function deleteRatingWithUndo(button) {
    const id = currentTrackId(button);
    const name = nickname();
    if (!id || !name || !window.OPED_DB?.deleteRating) return false;
    if (!window.confirm('Удалить твою оценку? Её можно будет вернуть в течение нескольких секунд.')) return true;

    const api = await firestore();
    const safeName = window.OPED_DB.normalizeNickname(name);
    const ref = api.doc(api.db, 'ratings', `${safeName}__${id}`);
    const snapshot = await api.getDoc(ref);
    const saved = snapshot.exists() ? snapshot.data() : null;
    const fields = ratingFields(button);

    await window.OPED_DB.deleteRating(id, name, fields);
    document.querySelector('#oc-opening-modal [data-modal-close]')?.click();

    toast('Оценка удалена.', {
      type: 'success',
      actionLabel: saved ? 'Отменить' : '',
      duration: 8000,
      onAction: saved ? async () => {
        await api.setDoc(ref, saved, { merge: false });
        toast('Оценка восстановлена ✓', { type: 'success', force: true });
      } : null
    });
    return true;
  }

  async function deleteTrackWithUndo(button) {
    const id = currentTrackId(button);
    if (!id || !window.OPED_DB?.deleteOpening) return false;
    const api = await firestore();
    const ref = api.doc(api.db, 'openings', id);
    const snapshot = await api.getDoc(ref);
    if (!snapshot.exists()) return false;
    const saved = snapshot.data();

    await window.OPED_DB.deleteOpening(id);
    window.OC_CATALOG_CACHE?.invalidate?.();
    toast('Трек удалён.', {
      type: 'success',
      actionLabel: 'Отменить',
      duration: 8000,
      onAction: async () => {
        await api.setDoc(ref, saved, { merge: false });
        window.OC_CATALOG_CACHE?.invalidate?.();
        toast('Трек восстановлен ✓', { type: 'success', force: true });
      }
    });
    return true;
  }

  document.addEventListener('click', event => {
    const open = event.target.closest('[data-action="open-card"]');
    if (open?.dataset?.id) lastOpenedTrackId = String(open.dataset.id);
  }, true);

  document.addEventListener('click', event => {
    const ratingDelete = event.target.closest('[data-action="delete-rating"],[data-action="all-delete-rating"],[data-card-action="delete-rating"]');
    if (ratingDelete) {
      event.preventDefault();
      event.stopImmediatePropagation();
      void deleteRatingWithUndo(ratingDelete).catch(error => {
        console.error('Undoable rating delete failed', error);
        toast('Не удалось удалить оценку.', { type: 'error', force: true });
      });
      return;
    }

    const trackDelete = event.target.closest('[data-action="delete"]');
    if (!trackDelete || trackDelete.getAttribute('data-confirm') !== '1') return;
    event.preventDefault();
    event.stopImmediatePropagation();
    void deleteTrackWithUndo(trackDelete).catch(error => {
      console.error('Undoable track delete failed', error);
      toast('Не удалось удалить трек.', { type: 'error', force: true });
    });
  }, true);

  window.__OC_UNDO_ACTIONS_READY__ = true;
})();

/* accessibility.js */
(() => {
  if (window.__OC_ACCESSIBILITY_READY__) return;

  const MODAL_SELECTORS = [
    '#oc-opening-modal', '#oc-season-evaluator', '#oc-auth-modal', '#oc-register-modal', '#oc-name-modal',
    '#oc-confirm-modal', '#oc-franchise-repair-modal', '#oc-image-migration-modal', '.oc-quality-modal', '.oc-hotkeys-help'
  ].join(',');

  function visible(element) {
    return Boolean(element && !element.classList.contains('hidden') && element.getClientRects().length);
  }

  function activeModal() {
    return [...document.querySelectorAll(MODAL_SELECTORS)].reverse().find(visible) || null;
  }

  function focusables(root) {
    return [...root.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex]:not([tabindex="-1"])')]
      .filter(element => element.getClientRects().length && element.getAttribute('aria-hidden') !== 'true');
  }

  function annotate() {
    const main = document.querySelector('#oc-main-panel');
    if (main && !main.id) main.id = 'oc-main-panel';
    document.querySelector('#oc-f-search')?.setAttribute('aria-label', 'Поиск по каталогу');
    document.querySelector('#oc-p-search')?.setAttribute('aria-label', 'Поиск в профиле');
    document.querySelector('.oc-topbar-nav')?.setAttribute('aria-label', 'Основная навигация');
    document.querySelector('#oc-daily-bell')?.setAttribute('aria-label', 'Ежедневная оценка');

    document.querySelectorAll(MODAL_SELECTORS).forEach(modal => {
      modal.setAttribute('role', 'dialog');
      modal.setAttribute('aria-modal', 'true');
    });
  }

  function addSkipLink() {
    if (document.querySelector('.oc-skip-link')) return;
    const link = document.createElement('a');
    link.className = 'oc-skip-link';
    link.href = '#oc-main-panel';
    link.textContent = 'Перейти к содержимому';
    document.body.prepend(link);
  }

  document.addEventListener('keydown', event => {
    if (event.key !== 'Tab') return;
    const modal = activeModal();
    if (!modal) return;
    const items = focusables(modal);
    if (!items.length) return;
    const first = items[0];
    const last = items[items.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      last.focus();
      event.preventDefault();
    } else if (!event.shiftKey && document.activeElement === last) {
      first.focus();
      event.preventDefault();
    }
  });

  document.addEventListener('click', event => {
    const opener = event.target.closest('[data-action="open-card"],#oc-auth-open,#oc-register-open,.oc-tab-btn');
    if (!opener) return;
    window.setTimeout(annotate, 0);
  }, true);

  window.__OC_ACCESSIBILITY_READY__ = true;
  const init = () => { addSkipLink(); annotate(); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
